  // Sort each inner array to ensure the first element is the smallest
  Input.forEach(arr => arr.sort());

  // Use the first element of each inner array as a key
  const keyMap = new Map();

  for (const arr of Input) {
    const key = arr[0];
    if (!keyMap.has(key)) {
      keyMap.set(key, arr);
    } else {
      // If the key already exists, check if the current array is a subset of the existing array
      const existingArray = keyMap.get(key);
      if (existingArray.length < arr.length) {
        keyMap.set(key, arr);
