  if (m > n) return 0; // Eulerian number is defined for m <= n
  if (m === 0) return 1; // Base case: A(0, 0) = 1
  if (m === 1) return n; // Base case: A(1, 1) = n
  let result = 0;
  for (let i = 0; i <= n; i++) {
    result += (-1) ** i * (n - i) * eulerian_num(n - 1, m - i);
  }
