function maxAverageOfPath(cost) {
  const N = cost.length;
  const dp = Array.from({ length: N }, () => Array(N).fill(0));

  // Initialize the first row and first column
  for (let i = 0; i < N; i++) {
    dp[0][i] = cost[0][i];
    if (i > 0) dp[0][i] += dp[0][i - 1];
  }

  for (let j = 0; j < N; j++) {
    dp[j][0] = cost[j][0];
    if (j > 0) dp[j][0] += dp[j - 1][0];
  }

  // Fill the dp table
  for (let i = 1; i < N; i++) {
    for (let j = 1; j < N; j++) {
      dp[i][j] = Math.max(cost[i][j] + dp[i - 1][j], cost[i][j] + dp[i][j - 1]);
    }
  }

  // The maximum average path is the maximum value in the bottom-right cell
  return dp[N - 1][N - 1] / N;
}

function maxAverageOfPath(cost){
  const N = cost.length;
  const dp = Array.from({ length: N }, () => Array(N).fill(0));

  // Fill the dp array
  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      if (i === 0 && j === 0) {
        dp[i][j] = cost[i][j];
      } else {
        const left = j > 0 ? dp[i][j - 1] : 0;
        const up = i > 0 ? dp[i - 1][j] : 0;
        dp[i][j] = cost[i][j] + Math.max(left, up);
      }
    }
  }

  // Find the maximum average path
  let maxAverage = -Infinity;
  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      let sum = dp[i][j];
      let count = 1;
      let row = i;
      let col = j;

      // Explore all possible paths from the current cell
      while (row < N - 1 || col < N - 1) {
        row++;
        col++;
        if (row < N && col < N) {
          sum += dp[row][col];
          count++;
        }
      }

      // Calculate the average and update the maximum average
      const average = sum / count;
      if (average > maxAverage) {
        maxAverage = average;
      }
    }
  }

  return maxAverage;
}

