    const minPathValues = [];

    const dfs = (row, col, pathLength, pathValues) => {
        if (pathLength === k) {
            minPathValues.push([...path]);
            return;
        }

        for (const [dr, dc] of directions) {
            const newRow = row + dr;
            const newCol = col + dc;
            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited[newRow][newCol]) {
                visited[newRow][newCol] = true;
                path.push(grid[newRow][newCol]);
                dfs(newRow, newCol, pathLength + 1, pathValues);
                path.pop();
                visited[newRow][newCol] = false;
            }
        }
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            visited[i][j] = true;
            path.push(grid[i][j]);
            dfs(i, j, 1, pathValues);
            path.pop();
            visited[i][j] = false;
        }
    }

    minPathValues.sort((a, b) => {
