function rgb_to_hsv(r, g, b) {
    let max = Math.max(r, g, b);
    let min = Math.min(r, g, b);
    let delta = max - min;

    let h, s, v;

    if (delta === 0) {
        h = 0;
        s = 0;
        v = max;
    } else {
        s = delta / max;

        if (r === max) {
            h = (g - b) / delta;
        } else if (g === max) {
            h = 2 + (b - r) / delta;
        } else {
            h = 4 + (r - g) / delta;
        }

        h = h / 6;
        if (h < 0) h += 1;
        if (h > 1) h -= 1;
    }

    v = max;

    return { h, s, v };
}

