  const min = Math.min(r, g, b);
  const delta = max - min;

  if (delta === 0) {
    return [0, 0, max];
  }

  const h = (g - b) / delta;
  const s = delta / max;

  if (r === max) {
    return [0, s, max];
  } else if (g === max) {
    return [60 * (h - 1), s, max];
  } else {
    return [60 * (h + 2), s, max];
  }
}

