function max_sum_increasing_subseq(a, n, index, k) {
    // Initialize a 2D array to store the maximum sum of increasing subsequence ending at each index
    const dp = Array.from({ length: n }, () => Array.from({ length: n }, () => 0));

    // Base case: The maximum sum of increasing subsequence ending at the first element is the element itself
    dp[0][0] = a[0];

    // Fill the dp array
    for (let i = 1; i < n; i++) {
        for (let j = 0; j <= i; j++) {
            if (j === 0 || a[j] < a[i]) {
                dp[i][j] = Math.max(dp[i][j], dp[i - 1][j] + a[i]);
            } else {
                dp[i][j] = Math.max(dp[i][j], dp[i - 1][j]);
            }
        }
    }

    // Find the maximum sum of increasing subsequence ending at the last element
    let max_sum = 0;
    for (let i = 0; i < n; i++) {
        max_sum = Math.max(max_sum, dp[i][n - 1]);
    }

    // Check if the kth element is after the current index and if it is included in the subsequence
    if (k > index && dp[index][k] > 0) {
        max_sum += a[k];
    }

    return max_sum;
}

