function find_First_Missing(array){
  if (array.length === 0) return 1; // Edge case for empty array

  let left = 0;
  let right = array.length - 1;

  while (left <= right) {
    let mid = Math.floor((left + right) / 2);

    // If the middle element is equal to its index, the missing number is in the right half
    if (array[mid] === mid) {
      left = mid + 1;
    } else {
      // If the middle element is not equal to its index, the missing number is in the left half
      right = mid - 1;
    }
  }

  // If the loop completes, the missing number is the next number after the last element
  return left + 1;
}

function find_First_Missing(array) {
    if (array.length === 0) return 1; // If the array is empty, the smallest missing number is 1

    let left = 0;
    let right = array.length - 1;

    while (left <= right) {
        let mid = Math.floor((left + right) / 2);

        // Check if the mid element is the smallest missing number
        if (array[mid] !== mid + 1) {
            return mid + 1;
        } else {
            // If the mid element is equal to its index + 1, the smallest missing number is in the left half
            right = mid - 1;
        }
    }

    // If no missing number is found, the smallest missing number is one more than the last element
    return array.length + 1;
}

