function newman_prime(n){
  let primeCount = 0;
  let num = 2;

  while (primeCount < n) {
    let isPrime = true;
    for (let i = 2; i <= Math.sqrt(num); i++) {
      if (num % i === 0) {
        isPrime = false;
        break;
      }
    }
    if (isPrime) {
      primeCount++;
    }
    num++;
  }

  return num - 1; // Adjusting for the initial increment of num
}

