    while(i < n && j < n){
        if(arr1[i] < arr2[j]){
            median = arr1[i];
            i++;
        } else {
            median = arr2[j];
            j++;
        }
        count++;
        if(count === (n + 1) / 2){
            break;
        }
    }
    if(count === (n + 1) / 2){
        if(n % 2 === 0){
            return (median + arr1[i]) / 2;
        } else {
            return median;
        }
    }
}

