function all_Bits_Set_In_The_Given_Range(n, l, r){
  // Convert the number to a binary string
  let binaryString = n.toString(2);

  // Iterate through the range l to r
  for(let i = l; i <= r; i++){
    // Check if the i-th bit is unset (0)
    if(binaryString[i] === '0'){
      return false;
    }
  }

  // If all bits are set, return true
  return true;
}

function all_Bits_Set_In_The_Given_Range(n, l, r){
    // Convert the range to a bitmask
    const mask = (1 << (r - l + 1)) - 1;
    // Shift the mask to the left by l positions
    const shifted_mask = mask << l;
    // Perform bitwise AND operation between the shifted mask and the given number
    const result = shifted_mask & n;
    // Check if the result is zero
    return result === 0;
}

function is_nested(string){
  let stack = [];
  for (let char of string) {
    if (char === '[') {
      stack.push(char);
    } else if (char === ']') {
      if (stack.length === 0) return false;
      stack.pop();
      if (stack.length > 0 && stack[stack.length - 1] === '[') {
        return true;
      }
    }
  }
  return false;
}

