function rgb_to_hsv(r, g, b) {
    let max = Math.max(r, g, b);
    let min = Math.min(r, g, b);
    let delta = max - min;

    let h;
    let s;
    let v = max;

    if (delta === 0) {
        h = 0;
        s = 0;
    } else {
        s = delta / v;

        let rNorm = (max - r) / delta;
        let gNorm = (max - g) / delta;
        let bNorm = (max - b) / delta;

        if (r === max) {
            h = gNorm - bNorm;
        } else if (g === max) {
            h = 2 + rNorm - bNorm;
        } else {
            h = 4 + bNorm - rNorm;
        }

        h /= 6;
        if (h < 0) h += 1;
    }

    return [h, s, v];
}

function rgb_to_hsv(r, g, b) {
    // Normalize RGB values to be between 0 and 1
    r /= 255;
    g /= 255;
    b /= 255;

    // Find the maximum and minimum values
    let max = Math.max(r, g, b);
    let min = Math.min(r, g, b);

    // Calculate the saturation
    let saturation = (max - min) / max;

    // Calculate the value
    let value = max;

    // Calculate the hue
    let hue;
    if (max === 0) {
        hue = 0;
    } else if (max === r) {
        hue = (g - b) / (max - min);
    } else if (max === g) {
        hue = (b - r) / (max - min) + 2;
    } else if (max === b) {
        hue = (r - g) / (max - min) + 4;
    }

    // Normalize hue to be between 0 and 360
    hue = (hue + 360) % 360;

    return { hue, saturation, value };
}

