function find_adverb_position(text){
  // Regular expression to find adverbs
  const adverbRegex = /\b[a-z]+ly\b/gi;
  // Find all adverbs in the text
  const adverbs = text.match(adverbRegex);
  // If no adverbs are found, return an empty array
  if (!adverbs) return [];
  // Initialize an array to store the positions of adverbs
  const positions = [];
  // Iterate over each adverb found
  adverbs.forEach((adverb, index) => {
    // Get the start and end positions of the adverb in the text
    const start = text.indexOf(adverb);
    const end = start + adverb.length;
    // Add the position of the adverb to the positions array
    positions.push({ adverb, start, end });
  });
  // Return the array of positions of adverbs
  return positions;
}

