function rgb_to_hsv(r, g, b) {
  // Normalize RGB values to the range [0, 1]
  r /= 255;
  g /= 255;
  b /= 255;

  // Find the maximum and minimum values in the RGB array
  let max = Math.max(r, g, b);
  let min = Math.min(r, g, b);

  // Calculate the saturation
  let saturation = max === 0 ? 0 : (max - min) / max;

  // Calculate the hue
  let hue = 0;
  if (max === r) {
    hue = (g - b) / (max - min);
  } else if (max === g) {
    hue = 2 + (b - r) / (max - min);
  } else {
    hue = 4 + (r - g) / (max - min);
  }

  // Convert hue from radians to degrees
  hue = hue * 180 / Math.PI;

  // Calculate the value
  let value = max;

  // Return the HSV values as an array
  return [hue, saturation, value];
}

function rgb_to_hsv(r, g, b) {
  let max = Math.max(r, g, b);
  let min = Math.min(r, g, b);
  let delta = max - min;

  let h;
  let s;
  let v = max;

  if (delta === 0) {
    h = 0;
    s = 0;
  } else {
    if (max === r) {
      h = (60 * ((g - b) / delta)) % 360;
    } else if (max === g) {
      h = (60 * ((b - r) / delta)) + 120;
    } else {
      h = (60 * ((r - g) / delta)) + 240;
    }

    s = delta / max;
  }

  return [h, s, v];
}

