function find_combinations(test_list) {
  const result = [];

  function backtrack(start, currentSum, path) {
    if (currentSum === 0) {
      result.push([...path]);
      return;
    }

    for (let i = start; i < test_list.length; i++) {
      if (test_list[i] > currentSum) continue;
      backtrack(i + 1, currentSum - test_list[i], [...path, test_list[i]]);
    }
  }

  backtrack(0, 0, []);
  return result;
}

function find_combinations(test_list){
    const result = [];
    const dfs = (index, currentSum, path) => {
        if (index === test_list.length) {
            if (currentSum === 0) {
                result.push(path.slice());
            }
            return;
        }
        path.push(test_list[index]);
        dfs(index + 1, currentSum + test_list[index], path);
        path.pop();
        dfs(index + 1, currentSum, path);
    };
    dfs(0, 0, []);
    return result;
}

