function minPath(grid, k) {
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
  const visited = new Set();
  const minPathLength = Infinity;
  const minPath = [];

  const dfs = (x, y, pathLength, path) => {
    if (pathLength === k) {
      if (path.length < minPathLength) {
        minPathLength = path.length;
        minPath = [...path];
      }
      return;
    }

    for (let i = 0; i < directions.length; i++) {
      const dx = directions[i][0];
      const dy = directions[i][1];
      const newX = x + dx;
      const newY = y + dy;

      if (newX >= 0 && newX < N && newY >= 0 && newY < N && !visited.has(`${newX},${newY}`)) {
        visited.add(`${newX},${newY}`);
        dfs(newX, newY, pathLength + 1, [...path, grid[newX][newY]]);
        visited.delete(`${newX},${newY}`);
      }
    }
  };

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      dfs(i, j, 1, [grid[i][j]]);
    }
  }

  return minPath;
}

function minPath(grid, k) {
    const N = grid.length;
    const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
    const visited = new Array(N).fill(0).map(() => new Array(N).fill(false));
    const queue = new PriorityQueue((a, b) => {
        return a[0] === b[0] ? a[1] - b[1] : a[0] - b[0];
    });

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            queue.enqueue([grid[i][j], [i, j], 0]);
        }
    }

    while (!queue.isEmpty()) {
        const [value, [x, y], steps] = queue.dequeue();
        if (steps === k) {
            return [value];
        }
        visited[x][y] = true;
        for (const [dx, dy] of directions) {
            const nx = x + dx;
            const ny = y + dy;
            if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny]) {
                queue.enqueue([grid[nx][ny], [nx, ny], steps + 1]);
            }
        }
    }
}

