    let h;
    let s;
    let v = max / 255;

    if (delta === 0) {
        h = 0;
        s = 0;
    } else {
        s = delta / max;

        let rc = (max - r) / delta;
        let gc = (max - g) / delta;
        let bc = (max - b) / delta;

        if (r === max) {
            h = (gc - bc) / delta;
        } else if (g === max) {
            h = 2 + (bc - rc) / delta;
        } else {
            h = 4 + (rc - gc) / delta;
        }

        h *= 60;
        if (h < 0) {
            h += 360;
        }
    }

    return { h, s, v };
}

