                j--;
            }
            digits[i] = digits[i] + digits[j];
            digits[j] = digits[i] - digits[j];
            digits.splice(i + 1, len - i - 1, ...digits.splice(i + 1, len - i - 1).reverse());
            found = true;
            break;
        }
    }

    if(!found){
        return -1;
    }

    return parseInt(digits.join(''));
}

function rearrange_bigger(n){
  // Convert number to string to manipulate digits
  let str = n.toString();
  let len = str.length;

  // Iterate from the second last digit to the first digit
  for (let i = len - 2; i >= 0; i--) {
    // Find the digit that is smaller than the current digit
    for (let j = i + 1; j < len; j++) {
      if (str[i] < str[j]) {
        // Swap the found digits
        let temp = str[i];
        str[i] = str[j];
        str[j] = temp;

        // Sort the digits to the right of the swapped digit
        let rightPart = str.slice(i + 1);
        rightPart.sort((a, b) => a - b);

        // Combine the parts to form the next bigger number
        return parseInt(str.slice(0, i + 1) + rightPart.join(''));
      }
    }
  }

  // If no bigger number is found, return -1
  return -1;
}

