function get_total_number_of_sequences(m, n){
  if (n === 1) return 1; // Base case: only one sequence of length 1
  let count = 0;
  for (let i = 2; i <= m; i++) {
    count += get_total_number_of_sequences(m, n - 1);
  }
  return count;
}

function get_total_number_of_sequences(m, n) {
  if (m < 2 || n < 1) return 0;
  let dp = new Array(n + 1).fill(0);
  dp[0] = 1; // There's one way to have an empty sequence
  for (let i = 1; i <= n; i++) {
    for (let j = m; j >= 2 * i; j--) {
      dp[i] += dp[j - 2 * i];
    }
  }
  return dp[n];
}

function eulerian_num(n, m){
    if (n === 0) return 1;
    if (m === 0) return 1;
    if (m > n) return 0;
    return (n - m) * eulerian_num(n - 1, m - 1) + eulerian_num(n - 1, m);
}

function eulerian_num(n, m) {
  if (m > n) {
    return 0;
  }
  if (m === 0) {
    return 1;
  }
  if (m === 1) {
    return n;
  }
  let result = 0;
  for (let i = 0; i <= n; i++) {
    result += (-1) ** i * Math.comb(n, i) * eulerian_num(n - i, m - 1);
  }
  return result;
}

