function minPath(grid, k) {
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
  const visited = new Array(N).fill().map(() => new Array(N).fill(false));
  const path = [];
  let minPathLength = Infinity;
  let minPath = [];

  const dfs = (row, col, pathLength, path) => {
    if (pathLength === k) {
      if (path.length < minPathLength || (path.length === minPathLength && path.join('') < minPath.join(''))) {
        minPathLength = pathLength;
        minPath = [...path];
      }
      return;
    }

    for (const [dr, dc] of directions) {
      const newRow = row + dr;
      const newCol = col + dc;
      if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited[newRow][newCol]) {
        visited[newRow][newCol] = true;
        path.push(grid[newRow][newCol]);
        dfs(newRow, newCol, pathLength + 1, path);
        path.pop();
        visited[newRow][newCol] = false;
      }
    }
  };

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      visited[i][j] = true;
      dfs(i, j, 1, [grid[i][j]]);
      visited[i][j] = false;
    }
  }

  return minPath;
}

function minPath(grid, k) {
  const N = grid.length;
  const visited = new Set();
  const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];

  function dfs(row, col, path, steps) {
    if (steps === k) {
      return path;
    }

    visited.add(`${row},${col}`);

    for (const [dx, dy] of directions) {
      const newRow = row + dx;
      const newCol = col + dy;

      if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited.has(`${newRow},${newCol}`)) {
        const newPath = [...path, grid[newRow][newCol]];
        const result = dfs(newRow, newCol, newPath, steps + 1);
        if (result) {
          return result;
        }
      }
    }

    visited.delete(`${row},${col}`);
    return null;
  }

  let minPath = null;
  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      const result = dfs(i, j, [grid[i][j]], 1);
      if (result) {
        if (!minPath || result.length < minPath.length) {
          minPath = result;
        }
      }
    }
  }

  return minPath;
}

