function max_sum_increasing_subseq(a, n, index, k) {
    if (index === n || k >= n) {
        return 0;
    }

    let includeK = a[k] + max_sum_increasing_subseq(a, n, index + 1, k);
    let excludeK = max_sum_increasing_subseq(a, n, index + 1, k);

    return Math.max(includeK, excludeK);
}

function max_sum_increasing_subseq(a, n, index, k) {
    if (index >= n || k >= n) return 0; // Base case: if index or k is out of bounds, return 0

    let maxSum = a[index];
    for (let i = index + 1; i < n; i++) {
        if (a[i] > a[index]) {
            maxSum = Math.max(maxSum, a[index] + max_sum_increasing_subseq(a, n, i, k));
        }
    }

    if (k < n) {
        maxSum = Math.max(maxSum, max_sum_increasing_subseq(a, n, index, k + 1));
    }

    return maxSum;
}

