function minPath(grid, k) {
    const N = grid.length;
    let minPath = [];
    let visited = new Set();

    function dfs(x, y, path, depth) {
        if (depth === k) {
            if (minPath.length === 0 || path < minPath) {
                minPath = [...path];
            }
            return;
        }

        const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];

        for (const [dx, dy] of directions) {
            const newX = x + dx;
            const newY = y + dy;

            if (newX >= 0 && newX < N && newY >= 0 && newY < N && !visited.has(`${newX},${newY}`)) {
                visited.add(`${newX},${newY}`);
                dfs(newX, newY, [...path, grid[newX][newY]], depth + 1);
                visited.delete(`${newX},${newY}`);
            }
        }
    }

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, [grid[i][j]], 1);
        }
    }

    return minPath;
}

function minPath(grid, k) {
    const n = grid.length;
    const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
    const visited = new Array(n).fill().map(() => new Array(n).fill(false));
    const path = [];
    const directionsQueue = [[0, 0, 0]]; // [row, col, steps]

    while (directionsQueue.length > 0) {
        const [row, col, steps] = directionsQueue.shift();

        if (steps === k) {
            path.push(grid[row][col]);
            continue;
        }

        if (steps >= n * n) continue;

        visited[row][col] = true;

        for (const [dx, dy] of directions) {
            const newRow = row + dx;
            const newCol = col + dy;

            if (newRow >= 0 && newRow < n && newCol >= 0 && newCol < n && !visited[newRow][newCol]) {
                directionsQueue.push([newRow, newCol, steps + 1]);
            }
        }
    }

    return path;
}

