function sequence(n) {
  if (n === 0) return 0;
  if (n === 1) return 1;

  const memo = new Map();
  memo.set(0, 0);
  memo.set(1, 1);

  function helper(m) {
    if (memo.has(m)) return memo.get(m);
    const result = helper(m - 1) + helper(m - 2);
    memo.set(m, result);
    return result;
  }

  return helper(n);
}

