function rearrange_bigger(n) {
  const digits = n.toString().split('').map(Number);
  let found = false;

  for (let i = digits.length - 2; i >= 0; i--) {
    if (digits[i] < digits[i + 1]) {
      for (let j = digits.length - 1; j > i; j--) {
        if (digits[j] > digits[i]) {
          [digits[i], digits[j]] = [digits[j], digits[i]];
          digits.splice(i + 1);
          digits.sort((a, b) => a - b);
          found = true;
          break;
        }
      }
      if (found) break;
    }
  }

  if (!found) return -1;

  return parseInt(digits.join(''));
}

function rearrange_bigger(n) {
    // Convert the number to an array of its digits
    const digits = n.toString().split('');

    // Find the first digit from the right that is smaller than the digit immediately to its right
    let i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such digit is found, the number is already the largest possible permutation
    if (i < 0) {
        return -1;
    }

    // Find the smallest digit to the right of the found digit that is larger than it
    let j = digits.length - 1;
    while (j > i && digits[j] <= digits[i]) {
        j--;
    }

    // Swap the found digits
    [digits[i], digits[j]] = [digits[j], digits[i]];

    // Reverse the digits to the right of the found digit
    digits.splice(i + 1);
    digits.reverse();

    // Convert the array of digits back to a number
    return parseInt(digits.join(''));
}

function find_combinations(test_list) {
