function minPath(grid, k) {
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];

  function dfs(row, col, path, count) {
    if (count === k) {
      return path;
    }

    const neighbors = [];
    for (const [dr, dc] of directions) {
      const newRow = row + dr;
      const newCol = col + dc;
      if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited[newRow][newCol]) {
        visited[newRow][newCol] = true;
        neighbors.push([newRow, newCol]);
      }
    }

    let minPath = Infinity;
    for (const [newRow, newCol] of neighbors) {
      const newPath = dfs(newRow, newCol, [...path, grid[newRow][newCol]], count + 1);
      if (newPath.length < minPath) {
        minPath = newPath;
      }
      visited[newRow][newCol] = false;
    }

    return minPath;
  }

  let minPath = Infinity;
  let visited = Array.from({ length: N }, () => Array(N).fill(false));
  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      visited[i][j] = true;
      const path = [grid[i][j]];
      const result = dfs(i, j, path, 1);
      if (result.length < minPath) {
        minPath = result;
      }
      visited[i][j] = false;
    }
  }

  return minPath;
}

function minPath(grid, k) {
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
  const visited = new Array(N).fill().map(() => new Array(N).fill(false));
  const path = [];
  const minPathLength = Infinity;
  const minPathValues = [];

  const dfs = (row, col, steps) => {
    if (steps === k) {
      if (path.length < minPathLength) {
        minPathLength = path.length;
        minPathValues = [...path];
      }
      return;
    }

    for (const [dx, dy] of directions) {
      const newRow = row + dx;
      const newCol = col + dy;

      if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited[newRow][newCol]) {
        visited[newRow][newCol] = true;
        path.push(grid[newRow][newCol]);
        dfs(newRow, newCol, steps + 1);
        path.pop();
        visited[newRow][newCol] = false;
      }
    }
  };

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      visited[i][j] = true;
      path.push(grid[i][j]);
      dfs(i, j, 1);
      path.pop();
      visited[i][j] = false;
    }
  }

  return minPathValues;
}

