function minPath(grid, k){
    let rows = grid.length;
    let cols = grid[0].length;
    let visited = new Array(rows).fill(null).map(() => new Array(cols).fill(false));
    let directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
    let minPath = [];

    function dfs(row, col, path, steps) {
        if (steps === k) {
            minPath.push(path.slice());
            return;
        }

        for (let dir of directions) {
            let newRow = row + dir[0];
            let newCol = col + dir[1];

            if (newRow >= 0 && newRow < rows && newCol >= 0 && newCol < cols && !visited[newRow][newCol]) {
                visited[newRow][newCol] = true;
                dfs(newRow, newCol, path.concat(grid[newRow][newCol]), steps + 1);
                visited[newRow][newCol] = false;
            }
        }
    }

    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            dfs(i, j, [grid[i][j]], 1);
        }
    }

    minPath.sort((a, b) => {
        for (let i = 0; i < a.length; i++) {
            if (a[i] !== b[i]) {
                return a[i] - b[i];
            }
        }
        return 0;
    });

    return minPath[0];
}

function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
    const visited = new Set();

    function dfs(x, y, path, steps) {
        if (steps === k) {
            return path;
        }
        visited.add(`${x},${y}`);
        let minPath = Infinity;
        for (const [dx, dy] of directions) {
            const newX = x + dx;
            const newY = y + dy;
            if (newX >= 0 && newX < N && newY >= 0 && newY < N && !visited.has(`${newX},${newY}`)) {
                const newPath = [...path, grid[newX][newY]];
                const newPathLength = newPath.length;
                const newPathValue = newPath[newPathLength - 1];
                const newPathMin = dfs(newX, newY, newPath, steps + 1);
                if (newPathMin !== Infinity && newPathMin < minPath) {
                    minPath = newPathMin;
                }
            }
        }
        visited.delete(`${x},${y}`);
        return minPath;
    }

    let minPathValue = Infinity;
    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            const path = [grid[i][j]];
            const minPath = dfs(i, j, path, 1);
            if (minPath !== Infinity && minPath < minPathValue) {
                minPathValue = minPath;
            }
        }
    }

    return minPathValue;
}

