function rearrange_bigger(n) {
    const digits = n.toString().split('');
    const len = digits.length;

    // Find the first digit from the right that is smaller than the digit immediately to its right
    let i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    if (i === -1) {
        return -1; // The number is the largest possible permutation
    }

    // Find the smallest digit to the right of i that is larger than digits[i]
    let j = len - 1;
    while (j >= 0 && digits[j] <= digits[i]) {
        j--;
    }

    // Swap digits[i] and digits[j]
    [digits[i], digits[j]] = [digits[j], digits[i]];

    // Sort the digits to the right of i in ascending order
    digits.splice(i + 1, len - i - 1).sort((a, b) => a - b);

    // Combine the digits to form the next bigger number
    return parseInt(digits.join(''));
}

function rearrange_bigger(n) {
    // Convert the number to an array of digits
    const digits = Array.from(String(n), Number);

    // Find the largest index i such that digits[i] < digits[i+1]
    let i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such index exists, return -1
    if (i === -1) {
        return -1;
    }

    // Find the largest index j such that digits[j] > digits[i]
    let j = digits.length - 1;
    while (j >= 0 && digits[j] <= digits[i]) {
        j--;
    }

    // Swap digits[i] and digits[j]
    [digits[i], digits[j]] = [digits[j], digits[i]];

    // Reverse the digits after index i
    digits.splice(i + 1);
    digits.reverse();

    // Convert the array of digits back to a number
    return parseInt(digits.join(''), 10);
}

