  let max = Math.max(r, g, b);
  let min = Math.min(r, g, b);

  // Calculate the saturation
  let saturation = max === 0 ? 0 : (max - min) / max;

  // Calculate the value
  let value = max;

  // Calculate the hue
  let hue;
  if (max === min) {
    hue = 0;
  } else if (max === r) {
    hue = (g - b) / (max - min);
  } else if (max === g) {
