    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const minPath = [];

    const dfs = (x, y, path) => {
        if (path.length === k) {
            minPath.push(path.slice());
            return;
        }

        for (const [dx, dy] of directions) {
            const nx = x + dx, ny = y + dy;
            if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny]) {
                visited[nx][ny] = true;
                dfs(nx, ny, path.concat(grid[nx][ny]));
                visited[nx][ny] = false;
            }
        }
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            visited[i][j] = true;
            dfs(i, j, [grid[i][j]]);
            visited[i][j] = false;
        }
    }

    minPath.sort((a, b) => {
        for (let i = 0; i < a.length && i < b.length; i++) {
            if (a[i] !== b[i]) {
                return a[i] - b[i];
            }
        }
        return a.length - b.length;
    });

    return minPath[0];
}

function minPath(grid, k) {
    const N = grid.length;
    const directions = [
        [1, 0], [-1, 0], [0, 1], [0, -1]
    ];
    const visited = new Array(N).fill(0).map(() => new Array(N).fill(false));
    const queue = [];
    const path = [];
    const minPathLength = Infinity;
    const result = [];

    // Start from any cell
    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            queue.push({ row: i, col: j, steps: 0 });
            visited[i][j] = true;
        }
    }

    while (queue.length > 0) {
        const { row, col, steps } = queue.shift();

        if (steps === k) {
            path.push(grid[row][col]);
            if (path.length < minPathLength) {
                minPathLength = path.length;
                result = [...path];
            }
            path.pop();
            continue;
        }

        for (const [dr, dc] of directions) {
            const newRow = row + dr;
            const newCol = col + dc;

            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited[newRow][newCol]) {
                visited[newRow][newCol] = true;
                queue.push({ row: newRow, col: newCol, steps: steps + 1 });
            }
        }
    }

    return result;
}

