function rgb_to_hsv(r, g, b) {
  // Normalize RGB values to the range [0, 1]
  r = r / 255;
  g = g / 255;
  b = b / 255;

  // Find the maximum and minimum values
  let max = Math.max(r, g, b);
  let min = Math.min(r, g, b);

  // Calculate the saturation
  let saturation = max === 0 ? 0 : (max - min) / max;

  // Calculate the value
  let value = max;

  // Calculate the hue
  let hue = 0;

  if (max === min) {
    hue = 0;
  } else if (r === max) {
    hue = (g - b) / (max - min);
  } else if (g === max) {
    hue = 2 + (b - r) / (max - min);
  } else {
    hue = 4 + (r - g) / (max - min);
  }

  // Convert hue to degrees
  hue = hue * 60;

  // Normalize hue to the range [0, 360]
  hue = hue % 360;

  // Return the HSV color as an array
  return [hue, saturation * 100, value * 100];
}

