function max_sum_increasing_subseq(a, n, index, k) {
  // Initialize a DP array to store the maximum sum of increasing subsequence up to each index
  const dp = new Array(n).fill(0);
  dp[index] = a[index]; // Base case: The sum of the first element is the element itself

  // Iterate through the array starting from the next element
  for (let i = index + 1; i < n; i++) {
    // Check if the current element can be included in the increasing subsequence
    if (a[i] > a[index]) {
      // Update the DP array with the maximum sum of increasing subsequence up to the current index
      dp[i] = Math.max(dp[i], dp[index] + a[i]);
    }
  }

  // Initialize a variable to keep track of the maximum sum of increasing subsequence including the given kth element
  let result = dp[index];

  // Iterate through the array starting from the next element
  for (let i = index + 1; i < n; i++) {
    // Check if the current element can be included in the increasing subsequence including the given kth element
    if (a[i] > a[index] && i > k) {
      // Update the result with the maximum sum of increasing subsequence including the given kth element
      result = Math.max(result, dp[index] + a[i]);
    }
  }

  return result;
}

function max_sum_increasing_subseq(a, n, index, k) {
    let dp = new Array(n + 1).fill(0);
    let prev = new Array(n + 1).fill(-1);

    for (let i = 0; i <= index; i++) {
        for (let j = i + 1; j <= n; j++) {
            if (a[j] > a[i] && dp[j] < dp[i] + a[j]) {
                dp[j] = dp[i] + a[j];
                prev[j] = i;
            }
        }
    }

    let maxSum = 0;
    let maxIndex = -1;
    for (let i = index + 1; i <= n; i++) {
        if (dp[i] > maxSum) {
            maxSum = dp[i];
            maxIndex = i;
        }
    }

    let sum = 0;
    let current = maxIndex;
    while (current !== -1) {
        sum += a[current];
        current = prev[current];
    }

    return sum;
}

