function tri(n){
  if (n === 0) return [3];
  if (n === 1) return [3, 2];
  if (n === 2) return [3, 2, 8];

  let sequence = [3, 2, 8];
  for (let i = 3; i <= n; i++) {
    if (i % 2 === 0) {
      sequence.push(sequence[i - 1] + 1);
    } else {
      sequence.push(sequence[i - 1] + sequence[i - 2] + sequence[i + 1]);
    }
  }
  return sequence;
}

