function eulerian_num(n, m) {
  if (m > n) return 0;
  if (m === 0) return 1;
  if (m === 1) return n;
  return (n - m) * eulerian_num(n - 1, m - 1) + eulerian_num(n - 1, m);
}

function eulerian_num(n, m){
  if (m > n) return 0;
  if (m === 0) return 1;
  if (m === 1) return n;
  if (n === 0) return 0;
  if (n === 1) return 1;
  let count = 0;
  for (let i = 0; i <= m; i++) {
    count += Math.pow(-1, i) * eulerian_num(n - i, m - i);
  }
  return count;
}

