function get_median(arr1, arr2, n){
    // Merge the two arrays and sort them
    let mergedArray = arr1.concat(arr2).sort((a, b) => a - b);
    // Calculate the median
    let median;
    if (n % 2 === 1) {
        // If the total number of elements is odd, return the middle element
        median = mergedArray[Math.floor(n / 2)];
    } else {
        // If the total number of elements is even, return the average of the two middle elements
        median = (mergedArray[n / 2 - 1] + mergedArray[n / 2]) / 2;
    }
    return median;
}

function get_median(arr1, arr2, n){
  let i = 0, j = 0, count = 0, median = 0;

  while (i < n && j < n) {
    if (arr1[i] < arr2[j]) {
      median = arr1[i];
      i++;
    } else {
      median = arr2[j];
      j++;
    }
    count++;

    if (count === n / 2) {
      break;
    }
  }

  if (n % 2 === 1) {
    return median;
  } else {
    let nextMedian;
    if (i < n) {
      nextMedian = arr1[i];
    } else {
      nextMedian = arr2[j];
    }
    return (median + nextMedian) / 2;
  }
}

