function find_adverb_position(text){
  // Split the text into words
  const words = text.split(' ');
  // Initialize variables to store the adverb and its position
  let adverb = '';
  let position = 0;
  // Iterate through the words to find the adverb
  for (let i = 0; i < words.length; i++) {
    if (words[i].includes('adverb')) {
      adverb = words[i];
      position = i + 1; // Position is 1-indexed
      break;
    }
  }
  // Return the adverb and its position
  return { adverb, position };
}

