}

function max_product(arr) {
    let n = arr.length;
    let dp = new Array(n).fill(1);
    let max_product = arr[0];

    for (let i = 1; i < n; i++) {
        for (let j = 0; j < i; j++) {
            if (arr[i] > arr[j] && dp[i] < dp[j] * arr[i]) {
                dp[i] = dp[j] * arr[i];
            }
        }
        max_product = Math.max(max_product, dp[i]);
    }

    return max_product;
}

