    const patternCount = colors.length / patternLength;

    for (let i = 0; i < patternLength; i++) {
        const pattern = patterns[i];
        let matchCount = 0;

        for (let j = 0; j < patternCount; j++) {
            if (colors[i * patternLength + j] === pattern) {
                matchCount++;
            }
        }

        if (matchCount < patternLength) {
            return false;
        }
    }

    return true;
}

