function minPath(grid, k) {
  const rows = grid.length;
  const cols = grid[0].length;
  const visited = new Array(rows).fill(null).map(() => new Array(cols).fill(false));
  const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
  const paths = [];

  function dfs(x, y, path, count) {
    if (count === k) {
      paths.push(path.slice());
      return;
    }

    for (const [dx, dy] of directions) {
      const nx = x + dx;
      const ny = y + dy;

      if (nx >= 0 && nx < rows && ny >= 0 && ny < cols && !visited[nx][ny]) {
        visited[nx][ny] = true;
        dfs(nx, ny, path.concat(grid[nx][ny]), count + 1);
        visited[nx][ny] = false;
      }
    }
  }

  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      dfs(i, j, [grid[i][j]], 1);
    }
  }

  paths.sort((a, b) => a < b ? -1 : 1);
  return paths[0];
}

function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const visited = new Array(N).fill().map(() => new Array(N).fill(false));
    const paths = [];

    function dfs(i, j, path, steps) {
        if (steps === k) {
            paths.push(path.slice());
            return;
        }

        for (const [dx, dy] of directions) {
            const nx = i + dx;
            const ny = j + dy;

            if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny]) {
                visited[nx][ny] = true;
                dfs(nx, ny, path.concat([grid[nx][ny]]), steps + 1);
                visited[nx][ny] = false;
            }
        }
    }

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            visited[i][j] = true;
            dfs(i, j, [grid[i][j]], 1);
            visited[i][j] = false;
        }
    }

    paths.sort((a, b) => a.toString() < b.toString());

    return paths[0];
}

