function eulerian_num(n, m) {
  if (m > n) return 0; // Eulerian numbers are non-negative and non-increasing
  if (m === 0) return 1;
  if (m === 1) return n;

  const dp = Array.from({ length: n + 1 }, (_, i) => Array.from({ length: m + 1 }, () => 0));
  dp[0][0] = 1;

  for (let i = 1; i <= n; i++) {
    for (let j = 1; j <= m; j++) {
      dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j];
      if (j < i) {
        dp[i][j] += dp[i - 1][j - i];
      }
    }
  }

  return dp[n][m];
}

function eulerian_num(n, m) {
  if (n < m) return 0;
  if (n === m) return 1;
  return (n - m) * eulerian_num(n - 1, m - 1) + eulerian_num(n - 1, m);
}

