function find_First_Missing(array){
  let start = 0;
  let end = array.length - 1;

  while (start <= end) {
    let mid = Math.floor((start + end) / 2);

    if (array[mid] === mid + 1) {
      start = mid + 1;
    } else {
      end = mid - 1;
    }
  }

  return start + 1;
}

function find_First_Missing(array) {
  // Check if the array is empty
  if (array.length === 0) {
    return 1; // The smallest missing number in an empty array is 1
  }

  // Check if the first element is 1, which means the smallest missing number is 1
  if (array[0] !== 1) {
    return 1;
  }

  // Use a binary search approach to find the smallest missing number
  let left = 0;
  let right = array.length - 1;

  while (left <= right) {
    let mid = Math.floor((left + right) / 2);

    // Check if the mid element is missing
    if (array[mid] !== mid + 1) {
      return mid + 1;
    } else if (array[mid] === mid + 1) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  // If no missing number is found, the smallest missing number is array.length + 1
  return array.length + 1;
}

