        for (let j = 0; j <= k; j++) {
            if (i === 0 || j === 0) {
                dp[i][j] = a[i];
            } else if (a[i] > a[j - 1]) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i - 1][j - 1] + a[i]);
            }
        }
    }

    // Return the maximum sum of increasing subsequence up to the last index and including the kth element
    return dp[n - 1][k];
}

