function rearrange_bigger(n) {
  const digits = n.toString().split('').map(Number);
  let found = false;

  for (let i = digits.length - 2; i >= 0; i--) {
    if (digits[i] < digits[i + 1]) {
      for (let j = digits.length - 1; j > i; j--) {
        if (digits[j] > digits[i]) {
          [digits[i], digits[j]] = [digits[j], digits[i]];
          digits.splice(i + 1);
          digits.sort((a, b) => a - b);
          found = true;
          break;
        }
      }
      if (found) break;
    }
  }

  if (!found) return -1;

  return parseInt(digits.join(''));
}

function rearrange_bigger(n) {
  let digits = n.toString().split('');
  let sortedDigits = digits.slice().sort((a, b) => b - a);
  let index = -1;

  // Find the first digit that is smaller than the digit immediately after it
  for (let i = digits.length - 2; i >= 0; i--) {
    if (digits[i] < digits[i + 1]) {
      index = i;
      break;
    }
  }

  // If no such digit is found, return -1
  if (index === -1) return -1;

  // Find the smallest digit to the right of the found digit that is greater than it
  let smallestIndex = index + 1;

  for (let i = index + 1; i < digits.length; i++) {
    if (digits[i] > digits[index] && digits[i] < digits[smallestIndex]) {
      smallestIndex = i;
    }
  }

  // Swap the found digits
  [digits[index], digits[smallestIndex]] = [digits[smallestIndex], digits[index]];

  // Sort the digits to the right of the found digit
  digits.splice(index + 1, digits.length - index - 1, ...sortedDigits.slice(index + 1));

  return parseInt(digits.join(''));
}

