        if (arr1[i] < arr2[j]) {
            mergedArray.push(arr1[i]);
            i++;
        } else {
            mergedArray.push(arr2[j]);
            j++;
        }
    }
    while (i < n) {
        mergedArray.push(arr1[i]);
        i++;
    }
    while (j < n) {
        mergedArray.push(arr2[j]);
        j++;
    }

    // Find the median of the merged array
    let mid = Math.floor(mergedArray.length / 2);
    if (mergedArray.length % 2 === 0) {
