function rearrange_bigger(n) {
  const digits = n.toString().split('');
  const length = digits.length;

  for (let i = length - 2; i >= 0; i--) {
    if (digits[i] < digits[i + 1]) {
      for (let j = length - 1; j > i; j--) {
        if (digits[j] > digits[i]) {
          [digits[i], digits[j]] = [digits[j], digits[i]];
          break;
        }
      }
      digits.splice(i + 1);
      digits.sort((a, b) => a - b);
      return parseInt(digits.join(''));
    }
  }

  return -1; // Return -1 if no bigger number can be formed
}

function rearrange_bigger(n){
    let digits = n.toString().split('');
    let sortedDigits = digits.sort((a, b) => b - a);
    let i = digits.length - 1;

    while (i > 0 && digits[i] <= digits[i - 1]) {
        i--;
    }

    if (i === 0) {
        return -1; // No bigger number can be formed
    }

    let j = i - 1;
    while (j < digits.length && digits[j] <= sortedDigits[i]) {
        j++;
    }

    [digits[i], digits[j]] = [digits[j], digits[i]];
    let remainingDigits = sortedDigits.slice(i + 1);
    remainingDigits.sort((a, b) => a - b);

    return parseInt(digits.join('')) + parseInt(remainingDigits.join(''));
}

