  add(num) {
    this.heap.push(num);
    this.bubbleUp(this.heap.length - 1);
  }

  poll() {
    if (this.size() === 1) {
      return this.heap.pop();
    }
    const root = this.heap[0];
    this.heap[0] = this.heap.pop();
    this.bubbleDown(0);
    return root;
  }

  bubbleUp(index) {
    while (index > 0 && this.heap[index] > this.heap[Math.floor((index - 1) / 2)]) {
      [this.heap[index], this.heap[Math.floor((index - 1) / 2)]] = [this.heap[Math.floor((index - 1) / 2)], this.heap[index]];
      index = Math.floor((index - 1) / 2);
    }
  }

  bubbleDown(index) {
    const left = 2 * index + 1;
    const right = 2 * index + 2;
    let largest = index;

    if (left < this.size() && this.heap[left] > this.heap[largest]) {
      largest = left;
    }

    if (right < this.size() && this.heap[right] > this.heap[largest]) {
      largest = right;
    }

    if (largest !== index) {
      [this.heap[index], this.heap[largest]] = [this.heap[largest], this.heap[index]];
      this.bubbleDown(largest);
    }
  }

  toArray() {
    return this.heap.slice();
  }
}

