    maxSum = Math.max(maxSum, maxSumWithK);
  }

  return maxSum;
}

function max_sum_increasing_subseq(a, n, index, k){
  let memo = new Array(n).fill(0);
  memo[index] = a[index]; // Base case: the sum of the first element is itself

  for (let i = index + 1; i < n; i++) {
    if (a[i] > a[index]) {
      memo[i] = Math.max(memo[i], memo[index] + a[i]);
    }
  }

  let maxSum = memo[index];
  for (let i = k + 1; i < n; i++) {
    if (a[i] > a[index]) {
      maxSum = Math.max(maxSum, memo[i] + a[i]);
    }
  }

  return maxSum;
}

