function get_total_number_of_sequences(m, n) {
  if (m < 2 || n < 1) {
    return 0;
  }
  let dp = Array.from({ length: n + 1 }, () => Array(m + 1).fill(0));
  dp[0][0] = 1; // There's one way to have a sequence of length 0 with a sum of 0

  for (let i = 1; i <= n; i++) {
    for (let j = 1; j <= m; j++) {
      if (i === 1) {
        dp[i][j] = Math.floor(j / 2); // Only one way to have a sequence of length 1 with a sum of j
      } else {
        dp[i][j] = dp[i - 1][j] + dp[i - 1][Math.min(j, 2 * (i - 1))]; // Add the number of sequences ending with j and the number of sequences ending with the minimum of j and 2 * (i - 1)
      }
    }
  }

  return dp[n][m];
}

