function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const visited = new Array(N).fill().map(() => new Array(N).fill(false));
    const path = [];
    const minPathValue = Infinity;
    const minPath = [];

    const dfs = (row, col, pathLength, pathValue) => {
        if (pathLength === k) {
            if (pathValue < minPathValue) {
                minPathValue = pathValue;
                minPath = [...path];
            }
            return;
        }

        for (const [dr, dc] of directions) {
            const newRow = row + dr;
            const newCol = col + dc;
            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited[newRow][newCol]) {
                visited[newRow][newCol] = true;
                path.push(grid[newRow][newCol]);
                dfs(newRow, newCol, pathLength + 1, pathValue + grid[newRow][newCol]);
                path.pop();
                visited[newRow][newCol] = false;
            }
        }
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            visited[i][j] = true;
            path.push(grid[i][j]);
            dfs(i, j, 1, grid[i][j]);
            path.pop();
            visited[i][j] = false;
        }
    }

    return minPath;
}

