        if (path.length === k) {
            minCost = cost;
            minPath = [...path];
            return;
        }
        visited.add(`${x},${y}`);
        for (const [dx, dy] of directions) {
            const nx = x + dx;
            const ny = y + dy;
            if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited.has(`${nx},${ny}`)) {
                dfs(nx, ny, cost + grid[nx][ny], [...path, grid[nx][ny]]);
            }
        }
        visited.delete(`${x},${y}`);
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, grid[i][j], [grid[i][j]]);
        }
    }

