function rearrange_bigger(n) {
    // Convert the number to an array of its digits
    const digits = Array.from(String(n), Number);

    // Start from the second last digit and move towards the first
    for (let i = digits.length - 2; i >= 0; i--) {
        // If the current digit is less than the digit immediately after it
        if (digits[i] < digits[i + 1]) {
            // Find the smallest digit to the right of the current digit that is larger than it
            let j = i + 1;
            while (j < digits.length && digits[j] <= digits[i]) {
                j++;
            }

            // Swap the found digits
            [digits[i], digits[j]] = [digits[j], digits[i]];

            // Sort the digits to the right of the current digit in ascending order
            digits.splice(i + 1, digits.length - i - 1).sort((a, b) => a - b);

            // Return the rearranged number as a string
            return parseInt(digits.join(''));
        }
    }

    // If no rearrangement is possible, return -1
    return -1;
}

function rearrange_bigger(n) {
