    const sumA = a.toString().split('').reduce((acc, digit) => acc + parseInt(digit), 0);
    const sumB = b.toString().split('').reduce((acc, digit) => acc + parseInt(digit), 0);
    if (sumA === sumB) {
      return nums.indexOf(a) - nums.indexOf(b);
    }
    return sumA - sumB;
  });
}

function find_length(string) {
  let maxDiff = 0;
  let zeroCount = 0;
  let oneCount = 0;

  for (let i = 0; i < string.length; i++) {
    if (string[i] === '0') {
      zeroCount++;
    } else {
      oneCount++;
    }

    if (zeroCount > oneCount) {
      maxDiff = Math.max(maxDiff, zeroCount - oneCount);
    }
  }

  return maxDiff;
}

