function bell_number(n){
  if (n === 0) return 1;
  let bell = [1];
  for (let i = 1; i <= n; i++) {
    let newBell = [0];
    for (let j = 0; j < bell.length; j++) {
      newBell[j + 1] += bell[j];
    }
    bell = newBell;
  }
  return bell[n];
}

function bell_number(n){
  if (n === 0) return 1;
  let bell = [1];
  for (let i = 1; i <= n; i++) {
    let next = 0;
    for (let j = 0; j < i; j++) {
      next += bell[j] * bell[i - j - 1];
    }
    bell.push(next);
  }
  return bell[n];
}

