function max_product(arr){
  let dp = Array(arr.length).fill(1);
  let max_product = 1;

  for (let i = 1; i < arr.length; i++) {
    for (let j = 0; j < i; j++) {
      if (arr[i] > arr[j]) {
        dp[i] = Math.max(dp[i], dp[j] * arr[i]);
        max_product = Math.max(max_product, dp[i]);
      }
    }
  }

  return max_product;
}

function max_product(arr) {
