function find_adverb_position(text){
  // Split the text into words
  const words = text.split(' ');

  // Iterate through the words to find the first adverb
  for (let i = 0; i < words.length; i++) {
    // Check if the word is an adverb
    if (/^[A-Za-z]+ly$/i.test(words[i])) {
      // Return the adverb and its position
      return { adverb: words[i], position: i + 1 };
    }
  }

  // Return null if no adverb is found
