    return 0;
  }

  // If the current element is greater than the previous element, include it in the sum
  if (index > 0 && a[index] > a[index - 1]) {
    return Math.max(a[index] + max_sum_increasing_subseq(a, n, index + 1, k), max_sum_increasing_subseq(a, n, index + 1, k));
