  // Explore all possible increasing subsequences starting from the current index
  for (let i = index + 1; i < n; i++) {
    if (a[i] > a[index]) {
      currentSum += a[i];
      maxSum = Math.max(maxSum, currentSum);
    }
  }

  // Explore all possible increasing subsequences starting from the next element after k
  for (let i = k + 1; i < n; i++) {
    if (a[i] > a[k]) {
      currentSum += a[i];
      maxSum = Math.max(maxSum, currentSum);
    }
  }

