  const index1 = planets.indexOf(planet1);
  const index2 = planets.indexOf(planet2);

  if (index1 === -1 || index2 === -1) {
    return [];
  }

  if (index1 > index2) {
    [index1, index2] = [index2, index1];
  }

  return planets.slice(index1 + 1, index2);
}

function do_algebra(operator, operand) {
    let result = operand[0];
    for (let i = 0; i < operator.length; i++) {
        switch (operator[i]) {
            case '+':
                result += operand[i + 1];
                break;
            case '-':
                result -= operand[i + 1];
                break;
            case '*':
                result *= operand[i + 1];
                break;
            case '//':
                result = Math.floor(result / operand[i + 1]);
                break;
            case '**':
                result = Math.pow(result, operand[i + 1]);
                break;
            default:
                throw new Error(`Unsupported operator: ${operator[i]}`);
        }
    }
    return result;
}

