function get_total_number_of_sequences(m, n) {
  if (m < 2) {
    return 0;
  }
  let dp = new Array(n + 1).fill(0);
  dp[0] = 1;
  for (let i = 1; i <= n; i++) {
    for (let j = 2; j <= m; j++) {
      if (j * 2 <= m) {
        dp[i] += dp[i - 1];
      }
    }
  }
  return dp[n];
}

function get_total_number_of_sequences(m, n) {
  // Initialize the result variable
  let result = 0;

  // Helper function to calculate the number of valid sequences of length k
  function countSequences(k, prev) {
    // Base case: if k is 0, there's exactly one valid sequence (the empty sequence)
    if (k === 0) {
      return 1;
    }

    // Initialize the count for the current sequence length
    let count = 0;

    // Iterate through possible values for the current element
    for (let i = Math.max(2, prev * 2); i <= m; i++) {
      // Recursively count the number of valid sequences of length k-1 with the current element
      count += countSequences(k - 1, i);
    }

    // Return the total count for the current sequence length
    return count;
  }

  // Calculate the total number of valid sequences of length n
  for (let i = 1; i <= n; i++) {
    result += countSequences(i, 0);
  }

  // Return the final result
  return result;
}

