function eulerian_num(n, m) {
  if (m > n) return 0;
  if (m === 0) return 1;
  if (m === 1) return n;
  return (n - 1) * (eulerian_num(n - 1, m - 1) + eulerian_num(n - 1, m));
}

function eulerian_num(n, m) {
  if (n === 0 && m === 0) return 1;
  if (n < 0 || m < 0 || n > m) return 0;

  let result = 0;
  for (let i = 0; i <= n; i++) {
    result += (-1) ** i * binomial_coefficient(n, i) * binomial_coefficient(m, n - i);
  }
  return result;
}

function binomial_coefficient(n, k) {
  if (k > n - k) k = n - k;
  let result = 1;
  for (let i = 0; i < k; i++) {
    result = result * (n - i) / (i + 1);
  }
  return result;
}

