function minPath(grid, k) {
  let rows = grid.length;
  let cols = grid[0].length;
  let visited = new Array(rows).fill(new Array(cols).fill(false));
  let directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  let result = [];

  const dfs = (i, j, path) => {
    if (path.length === k) {
      result.push(path);
      return;
    }

    for (let dir of directions) {
      let newRow = i + dir[0];
      let newCol = j + dir[1];

      if (newRow >= 0 && newRow < rows && newCol >= 0 && newCol < cols && !visited[newRow][newCol]) {
        visited[newRow][newCol] = true;
        dfs(newRow, newCol, path.concat(grid[newRow][newCol]));
        visited[newRow][newCol] = false;
      }
    }
  };

  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      dfs(i, j, [grid[i][j]]);
    }
  }

  // Sort the results lexicographically
  result.sort((a, b) => a.toString() < b.toString() ? -1 : 1);

  return result[0];
}

function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const visited = new Set();

    function dfs(row, col, path) {
        if (path.length === k) {
            visited.add(JSON.stringify(path));
            return path;
        }

        const current = grid[row][col];
        const key = JSON.stringify([row, col, path]);

        if (visited.has(key)) {
            return null;
        }

        visited.add(key);

        let minPath = null;

        for (const [dr, dc] of directions) {
            const newRow = row + dr;
            const newCol = col + dc;

            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N) {
                const result = dfs(newRow, newCol, path.concat(current));
                if (result && (minPath === null || result.join('') < minPath.join(''))) {
                    minPath = result;
                }
            }
        }

        return minPath;
    }

    let minPath = null;

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            const result = dfs(i, j, []);
            if (result && (minPath === null || result.join('') < minPath.join(''))) {
                minPath = result;
            }
        }
    }

    return minPath;
}

