function max_sum_increasing_subseq(a, n, index, k) {
    if (index === n) {
        return 0;
    }

    // Include the current element in the subsequence
    let include = a[index] + max_sum_increasing_subseq(a, n, index + 1, k);

    // Exclude the current element from the subsequence
    let exclude = max_sum_increasing_subseq(a, n, index + 1, k);

    // Return the maximum of including or excluding the current element
    return Math.max(include, exclude);
}

function max_sum_increasing_subseq(a, n, index, k) {
    if (index === n) return 0;

    let maxSum = a[index];
    for (let i = index + 1; i < n; i++) {
        if (a[i] > a[index]) {
            maxSum = Math.max(maxSum, max_sum_increasing_subseq(a, n, i, k) + a[i]);
        }
    }

    if (k > index) {
        maxSum = Math.max(maxSum, max_sum_increasing_subseq(a, n, k, k) + a[k]);
    }

    return maxSum;
}

