function minPath(grid, k){
  const N = grid.length;
  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const visited = new Set();

  function dfs(i, j, path, steps) {
    if (steps === k) {
      return [path];
    }

    const neighbors = directions.filter(([dx, dy]) => {
      const ni = i + dx;
      const nj = j + dy;
      return ni >= 0 && ni < N && nj >= 0 && nj < N && !visited.has(`${ni},${nj}`);
    });

    if (neighbors.length === 0) {
      return [];
    }

    const minPaths = [];
    for (const [dx, dy] of neighbors) {
      const ni = i + dx;
      const nj = j + dy;
      const newPath = [...path, grid[ni][nj]];
      visited.add(`${ni},${nj}`);
      const paths = dfs(ni, nj, newPath, steps + 1);
      minPaths.push(...paths);
      visited.delete(`${ni},${nj}`);
    }

    return minPaths;
  }

  let minPath = [];
  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      const paths = dfs(i, j, [grid[i][j]], 1);
      if (paths.length > 0) {
        minPath = paths[0];
        break;
      }
    }
    if (minPath.length > 0) break;
  }

  return minPath;
}

function minPath(grid, k) {
  const rows = grid.length;
  const cols = grid[0].length;
  const visited = new Array(rows).fill().map(() => new Array(cols).fill(false));
  const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
  const minPathLength = Infinity;
  const minPath = [];

  const dfs = (x, y, pathLength, path) => {
    if (pathLength === k) {
      if (path.length < minPathLength) {
        minPathLength = path.length;
        minPath = [...path];
      }
      return;
    }

    visited[x][y] = true;
    for (const [dx, dy] of directions) {
      const nx = x + dx;
      const ny = y + dy;
      if (nx >= 0 && nx < rows && ny >= 0 && ny < cols && !visited[nx][ny]) {
        dfs(nx, ny, pathLength + 1, [...path, grid[nx][ny]]);
      }
    }
    visited[x][y] = false;
  };

  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      dfs(i, j, 1, [grid[i][j]]);
    }
  }

  return minPath;
}

