function max_product(arr){
    let n = arr.length;
    let dp = new Array(n).fill(1);
    let max_product = arr[0];

    for(let i = 1; i < n; i++){
        for(let j = 0; j < i; j++){
            if(arr[i] > arr[j]){
                dp[i] = Math.max(dp[i], dp[j] * arr[i]);
                max_product = Math.max(max_product, dp[i]);
            }
        }
    }

    return max_product;
}

function max_product(arr){
  let max = arr[0];
  let secondMax = arr[0];
  let result = arr[0];

  for(let i = 1; i < arr.length; i++){
    if(arr[i] > max){
      secondMax = max;
      max = arr[i];
    } else if(arr[i] > secondMax && arr[i] !== max){
      secondMax = arr[i];
    }

    result = Math.max(result, max * secondMax);
  }

  return result;
}

