function max_sum_increasing_subseq(a, n, index, k) {
    // Initialize the dp array to store the maximum sum for each subsequence ending at index i
    const dp = new Array(n + 1).fill(0);
    dp[index] = a[index]; // Base case: the sum of the current element is the element itself

    // Iterate through the array starting from the next element after index
    for (let i = index + 1; i < n; i++) {
        // Check if the current element is greater than the element at index i
        if (a[i] > a[index]) {
            // Update the dp array with the maximum sum of the increasing subsequence ending at index i
            dp[i] = Math.max(dp[i], dp[index] + a[i]);
        }
    }

    // Iterate through the array starting from the next element after k
    for (let i = k + 1; i < n; i++) {
        // Check if the current element is greater than the element at index i
        if (a[i] > a[k]) {
            // Update the dp array with the maximum sum of the increasing subsequence ending at index i
            dp[i] = Math.max(dp[i], dp[k] + a[i]);
        }
    }

    // The maximum sum of the increasing subsequence ending at index k is the maximum value in the dp array
    return Math.max(...dp);
}

function max_sum_increasing_subseq(a, n, index, k) {
  if (index === n || k >= n) {
    return 0;
  }

  let maxSum = a[index];
  for (let i = index + 1; i < n; i++) {
    if (a[i] > a[index] && i > k) {
      maxSum = Math.max(maxSum, a[index] + max_sum_increasing_subseq(a, n, i, k));
    }
  }

  return maxSum;
}

