function group_tuples(Input){
  // Initialize an empty array to store the common first elements
  let commonFirstElements = [];

  // Iterate over each array in the input
  for (let i = 0; i < Input.length; i++) {
    // Check if the array is not empty
    if (Input[i].length > 0) {
      // If the commonFirstElements array is empty, add the first element of the current array
      if (commonFirstElements.length === 0) {
        commonFirstElements.push(Input[i][0]);
      } else {
        // If the commonFirstElements array is not empty, check if the current array's first element is the same as the last element of the commonFirstElements array
        if (Input[i][0] === commonFirstElements[commonFirstElements.length - 1]) {
          // If they are the same, add the current array's first element to the commonFirstElements array
          commonFirstElements.push(Input[i][0]);
        } else {
          // If they are not the same, return null as there is no common first element
          return null;
        }
      }
    }
  }

  // If the commonFirstElements array has only one element, return that element
  if (commonFirstElements.length === 1) {
    return commonFirstElements[0];
  }

  // If the commonFirstElements array has more than one element, return the array as the common first elements
  return commonFirstElements;
}

