function minPath(grid, k) {
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]]; // Right, Down, Up, Left
  const visited = new Set();
  const queue = [];
  const path = [];

  // Add all cells to the queue
  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      queue.push({ row: i, col: j, steps: 0 });
      visited.add(`${i},${j}`);
    }
  }

  while (queue.length > 0) {
    const { row, col, steps } = queue.shift();

    if (steps === k) {
      path.push(grid[row][col]);
      return path;
    }

    for (const [dx, dy] of directions) {
      const newRow = row + dx;
      const newCol = col + dy;

      if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited.has(`${newRow},${newCol}`)) {
        queue.push({ row: newRow, col: newCol, steps: steps + 1 });
        visited.add(`${newRow},${newCol}`);
      }
    }
  }

  return [];
}

function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const visited = new Array(N).fill().map(() => new Array(N).fill(false));
    const path = [];
    let minPathLength = Infinity;
    let minPath = [];

    const dfs = (i, j, steps) => {
        if (steps === k) {
            if (path.length < minPathLength) {
                minPath = [...path];
                minPathLength = path.length;
            }
            return;
        }

        visited[i][j] = true;
        path.push(grid[i][j]);

        for (const [dx, dy] of directions) {
            const x = i + dx;
            const y = j + dy;
            if (x >= 0 && x < N && y >= 0 && y < N && !visited[x][y]) {
                dfs(x, y, steps + 1);
            }
        }

        path.pop();
        visited[i][j] = false;
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, 0);
        }
    }

    return minPath;
}

