                minPathLength = steps;
                pathValues = path.slice();
            }
            return;
        }

        for (const [dx, dy] of directions) {
            const nx = x + dx;
            const ny = y + dy;
            if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny] && grid[nx][ny] !== 0) {
                visited[nx][ny] = true;
                path.push(grid[nx][ny]);
                dfs(nx, ny, steps + 1);
                path.pop();
                visited[nx][ny] = false;
            }
        }
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            if (grid[i][j] !== 0) {
                visited[i][j] = true;
                path.push(grid[i][j]);
                dfs(i, j, 1);
                path.pop();
                visited[i][j] = false;
            }
        }
    }

