function amicable_numbers_sum(limit) {
    function sumDivisors(n) {
        let sum = 1; // 1 is always a divisor
        for (let i = 2; i <= Math.sqrt(n); i++) {
            if (n % i === 0) {
                sum += i;
                if (i !== n / i) { // Avoid adding the square root twice for perfect squares
                    sum += n / i;
                }
            }
        }
        return sum;
    }

    let sum = 0;
    for (let i = 2; i <= limit; i++) {
        let divSum = sumDivisors(i);
        if (divSum > i && sumDivisors(divSum) === i) {
            sum += i;
        }
    }
    return sum;
}

