}

function eulerian_num(n, m) {
  if (n < 0 || m < 0 || m > n) {
    return 0;
  }
  if (n === 0) {
    return 1;
  }
  if (m === 0) {
    return 1;
  }
  if (m === n) {
    return 1;
  }
  if (m === 1) {
    return 2;
  }
  let result = 0;
  for (let i = 0; i <= n; i++) {
    result += (-1) ** (n - i) * binomial_coefficient(n, i) * binomial_coefficient(n - i, m - i);
  }
  return result;
}

function binomial_coefficient(n, k) {
  if (k > n - k) {
    k = n - k;
  }
  let result = 1;
  for (let i = 0; i < k; i++) {
    result *= (n - i);
    result /= (i + 1);
  }
  return result;
}

function eulerian_num(n, m) {
  if (n === 0 && m === 0) return 1;
  if (n === 0 || m === 0) return 0;
  if (m > n) return 0;

  let result = 0;
  for (let i = 0; i <= n; i++) {
    result += Math.pow(-1, i) * binomial_coefficient(n, i) * binomial_coefficient(n - i, m);
  }

  return result;
}

function binomial_coefficient(n, k) {
  if (k > n - k) k = n - k;
  let result = 1;
  for (let i = 1; i <= k; i++) {
    result *= (n - i + 1) / i;
  }
  return result;
}

