function bell_number(n){
  if (n === 0) return 1;
  let bell = [1];
  for (let i = 1; i <= n; i++) {
    let prev = bell[i - 1];
    let sum = 0;
    for (let j = 0; j < i; j++) {
      sum += bell[j] * prev;
    }
    bell.push(sum);
  }
  return bell[n];
}

function bell_number(n) {
  if (n === 0) return 1;
  let bell = [1];
  for (let i = 1; i <= n; i++) {
    let next = 0;
    for (let j = 0; j < i; j++) {
      next += bell[j] * bell[i - j - 1];
    }
    bell.push(next);
  }
  return bell[n];
}

