function generate_integers(a, b) {
  // Ensure a is less than or equal to b
  if (a > b) {
    [a, b] = [b, a];
  }

  // Initialize an empty array to store even digits
  const evenDigits = [];

  // Iterate through the range from a to b
  for (let i = a; i <= b; i++) {
    // Convert the number to a string to easily iterate over its digits
    const numStr = i.toString();

    // Iterate over each digit of the number
    for (let digit of numStr) {
      // Check if the digit is even
      if (parseInt(digit) % 2 === 0) {
        // Add the even digit to the array
        evenDigits.push(parseInt(digit));
      }
    }
  }

  // Sort the array of even digits in ascending order
  evenDigits.sort((a, b) => a - b);

  return evenDigits;
}

function rearrange_bigger(n) {
    const digits = n.toString().split('');
    let i = digits.length - 2;

    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    if (i === -1) {
        return -1; // No bigger number can be formed
    }

    let j = digits.length - 1;

    while (digits[j] <= digits[i]) {
        j--;
    }

    [digits[i], digits[j]] = [digits[j], digits[i]];

    digits.splice(i + 1);

    digits.sort((a, b) => a - b);

    return parseInt(digits.join(''));
}

function rearrange_bigger(n) {
  // Convert the number to an array of its digits
  const digits = Array.from(String(n), Number);

  // Find the first digit from the right that is smaller than the digit immediately to its right
  let i = digits.length - 2;
  while (i >= 0 && digits[i] >= digits[i + 1]) {
    i--;
  }

  // If no such digit is found, the number is already the largest permutation
  if (i === -1) {
    return -1;
  }

  // Find the smallest digit on the right side of i that is greater than digits[i]
  let j = digits.length - 1;
  while (j > i && digits[j] <= digits[i]) {
    j--;
  }

  // Swap digits[i] and digits[j]
  [digits[i], digits[j]] = [digits[j], digits[i]];

  // Sort the digits to the right of i in ascending order
  digits.splice(i + 1, digits.length - i - 1).sort((a, b) => a - b);

  // Convert the array of digits back to a number
  return parseInt(digits.join(''), 10);
}

