function max_sum_increasing_subseq(a, n, index, k) {
  if (index === n - 1) {
    return a[index];
  }

  let maxSum = a[index];
  for (let j = index + 1; j < n; j++) {
    if (a[j] > a[index] && j > k) {
      maxSum = Math.max(maxSum, a[j] + max_sum_increasing_subseq(a, n, j, k));
    }
  }

  return maxSum;
}

function max_sum_increasing_subseq(a, n, index, k) {
  // Initialize a DP array to store the maximum sum of increasing subsequence up to each index
  const dp = new Array(n).fill(0);

  // Iterate through the array to fill the DP array
  for (let i = index; i < n; i++) {
    // Find the maximum sum of increasing subsequence ending at the current index
    let maxSum = 0;
    for (let j = 0; j < i; j++) {
      if (a[j] < a[i] && dp[j] + a[i] > maxSum) {
        maxSum = dp[j] + a[i];
      }
    }
    // Update the DP array with the maximum sum of increasing subsequence up to the current index
    dp[i] = maxSum;
  }

  // Find the maximum sum of increasing subsequence including the kth element
  let maxSum = 0;
  for (let i = 0; i <= index; i++) {
    if (i < k) {
      maxSum += a[i];
    } else {
      maxSum += dp[i];
    }
  }

  return maxSum;
}

