function find_combinations(test_list){
  const combinations = [];
  const dfs = (index, currentSum, currentCombination) => {
    if (index === test_list.length) {
      if (currentSum === 0) {
        combinations.push(currentCombination.slice());
      }
      return;
    }
    currentCombination.push(test_list[index]);
    dfs(index + 1, currentSum + test_list[index], currentCombination);
    currentCombination.pop();
    dfs(index + 1, currentSum, currentCombination);
  };
  dfs(0, 0, []);
  return combinations;
}

