function all_Bits_Set_In_The_Given_Range(n, l, r){
    // Convert the range to a bitmask
    let bitmask = (1 << (r - l + 1)) - 1;
    // Apply the bitmask to the number n
    let result = n & bitmask;
    // Check if the result is zero
    return result === 0;
}

function all_Bits_Set_In_The_Given_Range(n, l, r){
    let mask = 0;
    for(let i = l; i <= r; i++){
        mask |= (1 << i);
    }
    return (n & mask) === 0;
}

