function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const visited = new Set();
    const queue = [[grid[0][0], 0, [grid[0][0]]]];

    while (queue.length > 0) {
        const [current, steps, path] = queue.shift();

        if (steps === k) {
            return path;
        }

        for (const [dx, dy] of directions) {
            const x = current[0] + dx;
            const y = current[1] + dy;

            if (x >= 0 && x < N && y >= 0 && y < N && !visited.has(`${x},${y}`)) {
                visited.add(`${x},${y}`);
                queue.push([grid[x][y], steps + 1, [...path, grid[x][y]]]);
            }
        }
    }

    return [];
}

function minPath(grid, k) {
  const n = grid.length;
  let minPath = [];
  let visited = new Array(n).fill(false).map(() => new Array(n).fill(false));
  let directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];

  const dfs = (x, y, path, steps) => {
    if (steps === k) {
      minPath = [...path];
      return;
    }
    visited[x][y] = true;

    for (const [dx, dy] of directions) {
      const nx = x + dx;
      const ny = y + dy;

      if (nx >= 0 && nx < n && ny >= 0 && ny < n && !visited[nx][ny]) {
        dfs(nx, ny, [...path, grid[nx][ny]], steps + 1);
      }
    }

    visited[x][y] = false;
  };

  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      dfs(i, j, [grid[i][j]], 1);
    }
  }

  return minPath;
}

