function get_total_number_of_sequences(m, n) {
    if (n === 0) return 1;
    if (n === 1) return m;
    let dp = new Array(m + 1).fill(0);
    dp[0] = 1;
    for (let i = 1; i <= m; i++) {
        dp[i] = dp[i - 1] * i;
    }
    let result = 0;
    for (let i = 1; i <= m; i++) {
        result += dp[m - i] * Math.pow(m - i + 1, n - 1);
    }
    return result;
}

