function group_tuples(Input){
    // Initialize an empty array to store the common elements
    let commonElements = [];

    // Iterate through the first array to find common elements
    for(let i = 0; i < Input[0].length; i++){
        let currentElement = Input[0][i];

        // Check if the current element exists in all other arrays
        let isCommon = true;
        for(let j = 1; j < Input.length; j++){
            if(Input[j].indexOf(currentElement) === -1){
                isCommon = false;
                break;
            }
        }

        // If the current element is common in all arrays, add it to the commonElements array
        if(isCommon){
            commonElements.push(currentElement);
        }
    }

    // Return the array of common elements
    return commonElements;
}

