function all_Bits_Set_In_The_Given_Range(n, l, r){
  // Convert the number to a binary string
  const binaryString = n.toString(2);

  // Extract the bits from the given range
  const bits = binaryString.substring(l - 1, r);

  // Check if all bits are set (1)
  for (let i = 0; i < bits.length; i++) {
    if (bits[i] === '0') {
      return false;
    }
  }

  return true;
}

function all_Bits_Set_In_The_Given_Range(n, l, r){
    // Check if the range is valid
    if (l < 0 || r >= n) {
        throw new Error("Invalid range");
    }

    // Create a mask with all bits set in the given range
    const mask = (1 << (r + 1)) - 1;

    // Apply the mask to the number and check if the result is zero
    const result = n & mask;

    // If the result is zero, all bits in the range are set
    return result === 0;
}

