function max_sum_increasing_subseq(a, n, index, k) {
    const dp = new Array(n).fill(0);
    dp[index] = a[index];
    let maxSum = dp[index];

    for (let i = index + 1; i < n; i++) {
        if (a[i] > a[index]) {
            dp[i] = Math.max(dp[i], dp[index] + a[i]);
            maxSum = Math.max(maxSum, dp[i]);
        }
    }

    for (let i = index + 1; i < n; i++) {
        if (a[i] > a[index] && i > k) {
            dp[i] = Math.max(dp[i], dp[k] + a[i]);
            maxSum = Math.max(maxSum, dp[i]);
        }
    }

    return maxSum;
}

function max_sum_increasing_subseq(a, n, index, k) {
  if (index === n - 1) {
    return a[index];
  }

  let maxSum = a[index];
  for (let i = index + 1; i < n; i++) {
    if (a[i] > a[index] && i > k) {
      maxSum = Math.max(maxSum, max_sum_increasing_subseq(a, n, i, k) + a[i]);
    }
  }

  return maxSum;
}

