  let zeroCount = 0;
  let oneCount = 0;

  for (let i = 0; i < string.length; i++) {
    if (string[i] === '0') {
      zeroCount++;
    } else {
      oneCount++;
    }

    maxDiff = Math.max(maxDiff, zeroCount - oneCount);
  }

  return maxDiff;
}

