function tri(n){
  if(n === 0) return [0];
  if(n === 1) return [0, 1];
  if(n === 2) return [0, 1, 2];

  let sequence = [0, 1, 2];
  for(let i = 3; i <= n; i++){
    if(i % 2 === 0){
      sequence[i] = sequence[i - 1] + sequence[i - 2];
    } else {
      sequence[i] = sequence[i - 1] + sequence[i - 2] + sequence[i + 1];
    }
  }
  return sequence;
}

function tri(n){
  if (n === 0) return [];
  if (n === 1) return [3];
  if (n === 2) return [3, 2];

  let result = [3, 3, 2];
  for (let i = 3; i <= n; i++) {
    if (i % 2 === 0) {
      result.push(1 + i / 2);
    } else {
      result.push(result[i - 1] + result[i - 2] + result[i + 1]);
    }
  }
  return result;
}

