function max_Product(arr){
    if (arr.length < 2) {
        return null; // Not enough elements to form a pair
    }

    let max1 = arr[0];
    let max2 = arr[1];
    let min1 = arr[0];
    let min2 = arr[1];

    for (let i = 2; i < arr.length; i++) {
        if (arr[i] > max1) {
            max2 = max1;
            max1 = arr[i];
        } else if (arr[i] > max2) {
            max2 = arr[i];
        }

        if (arr[i] < min1) {
            min2 = min1;
            min1 = arr[i];
        } else if (arr[i] < min2) {
            min2 = arr[i];
        }
    }

