function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const visited = new Array(N).fill().map(() => new Array(N).fill(false));
    const minPath = [];
    const pathLength = 0;

    const dfs = (x, y, path) => {
        if (pathLength === k) {
            minPath.push(...path);
            return;
        }

        for (const [dx, dy] of directions) {
            const nx = x + dx;
            const ny = y + dy;

            if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny]) {
                visited[nx][ny] = true;
                path.push(grid[nx][ny]);
                dfs(nx, ny, path);
                path.pop();
                visited[nx][ny] = false;
            }
        }
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            visited[i][j] = true;
            dfs(i, j, [grid[i][j]]);
            visited[i][j] = false;
        }
    }

    return minPath;
}

