    function dfs(x, y, path, steps) {
        if (steps === k) {
            minPath = [...path];
            return;
        }

        visited[x][y] = true;

        for (const [dx, dy] of directions) {
            const nx = x + dx;
            const ny = y + dy;

            if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny]) {
                dfs(nx, ny, [...path, grid[nx][ny]], steps + 1);
            }
        }

        visited[x][y] = false;
    }

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, [grid[i][j]], 1);
        }
    }

    return minPath;
}

