function eulerian_num(n, m) {
  if (n === 0) return 1;
  if (m === 0) return 0;
  if (m > n) return 0;

  const memo = new Array(n + 1).fill(null).map(() => new Array(m + 1).fill(null));

  for (let i = 0; i <= n; i++) {
    for (let j = 0; j <= m; j++) {
