function minPath(grid, k) {
    const N = grid.length;
    const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
    const visited = new Array(N).fill().map(() => new Array(N).fill(false));
    const path = [];
    const minPathValue = Infinity;
    const minPath = [];

    function dfs(x, y, steps) {
        if (steps === k) {
            if (path.length < minPath.length || (path.length === minPath.length && path.join(',') < minPath.join(','))) {
                minPath = [...path];
                minPathValue = steps;
            }
            return;
        }

        for (const [dx, dy] of directions) {
            const nx = x + dx;
            const ny = y + dy;
            if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny]) {
                visited[nx][ny] = true;
                path.push(grid[nx][ny]);
                dfs(nx, ny, steps + 1);
                path.pop();
                visited[nx][ny] = false;
            }
        }
    }

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            visited[i][j] = true;
            path.push(grid[i][j]);
            dfs(i, j, 1);
            path.pop();
            visited[i][j] = false;
        }
    }

    return minPath;
}

function minPath(grid, k) {
    let rows = grid.length;
    let cols = grid[0].length;
    let directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
    let visited = new Array(rows).fill().map(() => new Array(cols).fill(false));
    let minPath = [];

    const dfs = (x, y, path, steps) => {
        if (steps === k) {
            minPath.push(path.slice());
            return;
        }

        for (let [dx, dy] of directions) {
            let nx = x + dx;
            let ny = y + dy;
            if (nx >= 0 && nx < rows && ny >= 0 && ny < cols && !visited[nx][ny]) {
                visited[nx][ny] = true;
                dfs(nx, ny, path.concat(grid[nx][ny]), steps + 1);
                visited[nx][ny] = false;
            }
        }
    };

    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            dfs(i, j, [grid[i][j]], 1);
        }
    }

    minPath.sort((a, b) => a.join(',') < b.join(',') ? -1 : 1);
    return minPath[0];
}

