function rearrange_bigger(n){
    // Convert the number to an array of its digits
    const digits = n.toString().split('');

    // Start from the second last digit and move towards the first digit
    for (let i = digits.length - 2; i >= 0; i--) {
        // Find the first digit that is smaller than the digit immediately after it
        for (let j = i + 1; j < digits.length; j++) {
            if (digits[i] < digits[j]) {
                // Swap these two digits
                [digits[i], digits[j]] = [digits[j], digits[i]];
                // Sort the digits to the right of the swapped digit
                digits.splice(i + 1);
                digits.sort((a, b) => a - b);
                // Combine the digits back into a number and return
                return parseInt(digits.join(''));
            }
        }
    }
    // If no such number can be formed, return -1
    return -1;
}

function rearrange_bigger(n) {
  const digits = n.toString().split('').sort((a, b) => b - a);
  let i = digits.length - 1;

  while (i > 0 && digits[i] <= digits[i - 1]) {
    i--;
  }

  if (i === 0) {
    return -1; // The number is the largest permutation of its digits.
  }

  let j = i - 1;
  while (digits[j] <= digits[i]) {
    j--;
  }

  [digits[i], digits[j]] = [digits[j], digits[i]];

  digits.splice(i + 1);

  digits.sort((a, b) => a - b);

  return parseInt(digits.join(''));
}

