function minPath(grid, k) {
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];

  function dfs(grid, x, y, path, count) {
    if (count === k) {
      return path;
    }

    for (const [dx, dy] of directions) {
      const nx = x + dx;
      const ny = y + dy;

      if (nx >= 0 && nx < N && ny >= 0 && ny < N && !path.includes(grid[nx][ny])) {
        const newPath = [...path, grid[nx][ny]];
        const result = dfs(grid, nx, ny, newPath, count + 1);
        if (result) {
          return result;
        }
      }
    }

    return null;
  }

  let minPath = null;
  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      const result = dfs(grid, i, j, [grid[i][j]], 1);
      if (result && (!minPath || result.length < minPath.length)) {
        minPath = result;
      }
    }
  }

  return minPath;
}

function minPath(grid, k) {
  const N = grid.length;
  const visited = new Array(N).fill(0).map(() => new Array(N).fill(false));
  let minPath = [];
  let minPathLength = Infinity;

  function dfs(row, col, steps, currentPath) {
    if (steps === k) {
      if (currentPath.length < minPathLength || (currentPath.length === minPathLength && currentPath < minPath)) {
        minPath = [...currentPath];
        minPathLength = currentPath.length;
      }
      return;
    }

    for (let dr = -1; dr <= 1; dr++) {
      for (let dc = -1; dc <= 1; dc++) {
        if (dr === 0 && dc === 0) continue;
        const newRow = row + dr;
        const newCol = col + dc;

        if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited[newRow][newCol] && grid[newRow][newCol] > 0) {
          visited[newRow][newCol] = true;
          dfs(newRow, newCol, steps + 1, [...currentPath, grid[newRow][newCol]]);
          visited[newRow][newCol] = false;
        }
      }
    }
  }

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      if (grid[i][j] > 0) {
        dfs(i, j, 1, [grid[i][j]]);
      }
    }
  }

  return minPath;
}

