    if (pathLength === k) {
      if (pathValues < minPathValues[0]) {
        minPathValues[0] = pathValues;
        path[0] = grid[row][col];
      }
      return;
    }

    for (const [dx, dy] of directions) {
      const newRow = row + dx;
      const newCol = col + dy;
      if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited[newRow][newCol]) {
        visited[newRow][newCol] = true;
        path.push(grid[newRow][newCol]);
        dfs(newRow, newCol, pathLength + 1, pathValues + grid[newRow][newCol]);
        path.pop();
        visited[newRow][newCol] = false;
      }
    }
  }

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      visited[i][j] = true;
      dfs(i, j, 1, grid[i][j]);
      visited[i][j] = false;
    }
  }

