  const digits = n.toString().split('');
  let found = false;

  for (let i = digits.length - 2; i >= 0; i--) {
    if (digits[i] < digits[i + 1]) {
      for (let j = digits.length - 1; j > i; j--) {
        if (digits[j] > digits[i]) {
          [digits[i], digits[j]] = [digits[j], digits[i]];
          digits.splice(i + 1);
          digits.sort((a, b) => a - b);
          found = true;
          break;
        }
      }
      if (found) break;
    }
  }

  if (!found) return -1;

  return parseInt(digits.join(''));
}

function rearrange_bigger(n) {
    let str = n.toString();
    let digits = str.split('');
    let len = digits.length;
    let i = len - 2;

    // Find the first digit from the right that is smaller than the digit immediately to its right
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    if (i === -1) {
        return -1; // No bigger number can be formed
    }

    // Find the smallest digit to the right of i that is greater than digits[i]
    let j = len - 1;
    while (j > i && digits[j] <= digits[i]) {
        j--;
    }

    // Swap digits[i] and digits[j]
    [digits[i], digits[j]] = [digits[j], digits[i]];

    // Sort the digits to the right of i in ascending order
    let rightPart = digits.slice(i + 1).sort((a, b) => a - b);

    // Combine the parts
    let result = digits.slice(0, i + 1).concat(rightPart);

    return parseInt(result.join(''), 10);
}

