function max_sum_increasing_subseq(a, n, index, k) {
    if (index === n) {
        return 0;
    }

    let maxSum = a[index];
    for (let i = index + 1; i < n; i++) {
        if (a[i] > a[index]) {
            maxSum = Math.max(maxSum, a[index] + max_sum_increasing_subseq(a, n, i, k));
        }
    }

    if (k > index) {
        maxSum = Math.max(maxSum, a[index] + max_sum_increasing_subseq(a, n, index + 1, k));
    }

    return maxSum;
}

function max_sum_increasing_subseq(a, n, index, k) {
    // Initialize a DP array to store the maximum sum of increasing subsequence ending at each index
    const dp = new Array(n).fill(0);

    // Iterate through each element in the array
    for (let i = 0; i < n; i++) {
        // If the current element is greater than the previous element and the index is less than k, update the DP array
        if (a[i] > a[index] && i < k) {
            dp[i] = Math.max(dp[i], dp[index] + a[i]);
        }

        // Update the maximum sum of increasing subsequence ending at the current index
        dp[i] = Math.max(dp[i], dp[i - 1]);
    }

    // Return the maximum sum of increasing subsequence ending at the last index
    return dp[n - 1];
}

