function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const visited = new Array(N).fill().map(() => new Array(N).fill(false));
    const path = [];
    const minPathValues = [];

    const dfs = (row, col, steps) => {
        if (steps === k) {
            minPathValues.push([...path]);
            return;
        }

        for (const [dx, dy] of directions) {
            const newRow = row + dx;
            const newCol = col + dy;

            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited[newRow][newCol]) {
                visited[newRow][newCol] = true;
                path.push(grid[newRow][newCol]);
                dfs(newRow, newCol, steps + 1);
                path.pop();
                visited[newRow][newCol] = false;
            }
        }
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            visited[i][j] = true;
            path.push(grid[i][j]);
            dfs(i, j, 1);
            path.pop();
            visited[i][j] = false;
        }
    }

    minPathValues.sort((a, b) => {
        for (let i = 0; i < Math.min(a.length, b.length); i++) {
            if (a[i] !== b[i]) {
                return a[i] - b[i];
            }
        }
        return a.length - b.length;
    });

    return minPathValues[0];
}

function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    let visited = new Set();
    let minPath = [];
    let minCost = Infinity;

    function dfs(row, col, cost, path) {
        if (cost > minCost) return;
        if (path.length === k) {
            if (cost < minCost) {
                minCost = cost;
                minPath = [...path];
            }
            return;
        }

        visited.add(`${row}-${col}`);
        for (const [dr, dc] of directions) {
            const newRow = row + dr;
            const newCol = col + dc;
            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited.has(`${newRow}-${newCol}`)) {
                dfs(newRow, newCol, cost + grid[newRow][newCol], [...path, grid[newRow][newCol]]);
            }
        }
        visited.delete(`${row}-${col}`);
    }

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, grid[i][j], [grid[i][j]]);
        }
    }

    return minPath;
}

