    if (m < 2) return 0; // No valid sequences if m is less than 2
    let count = 0;
    for (let i = 1; i <= m; i++) {
        count += helper(i, n, 1); // Recursively count sequences starting with i
    }
    return count;
}

function helper(current, remaining, start) {
    if (remaining === 0) return 1; // Found a valid sequence
    let count = 0;
    for (let i = start; i <= m; i++) {
        if (i >= 2 * current) {
            count += helper(i, remaining - 1, i); // Recursively count sequences starting with i
        }
    }
    return count;
}

