function bell_number(n) {
  // Bell numbers can be calculated using the recurrence relation:
  // B(n) = sum(B(i) * C(n, i)) for i from 0 to n
  // where C(n, i) is the binomial coefficient C(n, i) = n! / (i! * (n-i)!)
  // Base case: B(0) = 1
  if (n === 0) return 1;

  let bell = [1];
  for (let i = 1; i <= n; i++) {
    let sum = 0;
    for (let j = 0; j < i; j++) {
      sum += bell[j] * comb(i, j);
    }
    bell.push(sum);
  }
  return bell[n];
}

