function max_sum_increasing_subseq(a, n, index, k) {
    // Initialize a 2D array to store the maximum sum of increasing subsequence up to each index
    const dp = new Array(n).fill(0).map(() => new Array(n).fill(0));

    // Fill the dp array
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            if (i === j) {
                dp[i][j] = a[i];
            } else if (i < j) {
                dp[i][j] = Math.max(dp[i][j-1], a[j] + (j > index && k > j ? dp[index+1][k] : 0));
            }
        }
    }

    // The maximum sum of increasing subsequence up to the last index including the kth element
    return dp[n-1][k];
}

function max_sum_increasing_subseq(a, n, index, k) {
    if (index === n) {
        return 0;
    }

    let maxSum = a[index];
    for (let i = index + 1; i < n; i++) {
        if (a[i] > a[index]) {
            maxSum = Math.max(maxSum, a[index] + max_sum_increasing_subseq(a, n, i, k));
        }
    }

    if (k > index && k < n) {
        maxSum = Math.max(maxSum, a[index] + max_sum_increasing_subseq(a, n, k, k));
    }

    return maxSum;
}

