function minPath(grid, k) {
  const N = grid.length;
  const visited = new Set();
  const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];

  const dfs = (x, y, path, count) => {
    if (count === k) {
      return path;
    }

    visited.add(`${x},${y}`);

    for (const [dx, dy] of directions) {
      const nx = x + dx;
      const ny = y + dy;

      if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited.has(`${nx},${ny}`)) {
        const newPath = [...path, grid[nx][ny]];
        const result = dfs(nx, ny, newPath, count + 1);
        if (result) {
          return result;
        }
      }
    }

    visited.delete(`${x},${y}`);
    return null;
  };

  let result = null;
  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      const path = [grid[i][j]];
      const result = dfs(i, j, path, 1);
      if (result) {
        return result;
      }
    }
  }

  return result;
}

function minPath(grid, k) {
