function minPath(grid, k) {
    const rows = grid.length;
    const cols = grid[0].length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];

    function dfs(row, col, steps, path) {
        if (steps === k) {
            return path;
        }

        const visited = new Set();
        const queue = [[row, col, steps, path]];

        while (queue.length) {
            const [x, y, steps, path] = queue.shift();

            if (visited.has(`${x},${y}`)) continue;
            visited.add(`${x},${y}`);

            path.push(grid[x][y]);

            for (const [dx, dy] of directions) {
                const newX = x + dx;
                const newY = y + dy;

                if (newX >= 0 && newX < rows && newY >= 0 && newY < cols) {
                    queue.push([newX, newY, steps + 1, [...path]]);
                }
            }
        }

        return null;
    }

    let minPath = null;
    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            const result = dfs(i, j, 0, [grid[i][j]]);
            if (result && (minPath === null || result.length < minPath.length)) {
                minPath = result;
            }
        }
    }

    return minPath;
}

function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]]; // Right, Down, Up, Left
    const visited = new Array(N).fill().map(() => new Array(N).fill(false));
    const path = [];
    const minPathLength = Infinity;
    const pathValues = [];

    function dfs(row, col, length, pathValues) {
        if (length === k) {
            if (pathValues.length < minPathLength) {
                minPathLength = pathValues.length;
                pathValues = [...path];
            }
            return;
        }

        for (const [dr, dc] of directions) {
            const newRow = row + dr;
            const newCol = col + dc;
            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited[newRow][newCol]) {
                visited[newRow][newCol] = true;
                path.push(grid[newRow][newCol]);
                dfs(newRow, newCol, length + 1, pathValues);
                path.pop();
                visited[newRow][newCol] = false;
            }
        }
    }

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            visited[i][j] = true;
            path.push(grid[i][j]);
            dfs(i, j, 1, pathValues);
            path.pop();
            visited[i][j] = false;
        }
    }

    return pathValues;
}

