        sum += i + (num / i);
      }
    }
    return sum === num ? true : false;
  };

  let sum = 0;
  for (let i = 2; i <= limit; i++) {
    if (isAmicable(i) && isAmicable(limit - i)) {
      sum += i + (limit - i);
    }
  }

  return sum;
}

