function max_sum_increasing_subseq(a, n, index, k) {
    let dp = new Array(n + 1).fill(0);
    let max_sum = 0;

    for (let i = 0; i <= index; i++) {
        dp[i] = a[i];
        max_sum = Math.max(max_sum, dp[i]);
    }

    for (let i = index + 1; i < n; i++) {
        if (a[i] > a[index] && dp[i] < dp[index] + a[i]) {
            dp[i] = dp[index] + a[i];
            max_sum = Math.max(max_sum, dp[i]);
        }
    }

    for (let i = index + 1; i < n; i++) {
        if (a[i] > a[k] && dp[i] < dp[k] + a[i]) {
            dp[i] = dp[k] + a[i];
            max_sum = Math.max(max_sum, dp[i]);
        }
    }

    return max_sum;
}

function max_sum_increasing_subseq(a, n, index, k) {
    if (index >= n) {
        return 0;
    }
    if (k >= n) {
        return a[index];
    }
    let maxSum = a[index];
    for (let i = index + 1; i < n; i++) {
        if (a[i] > a[index]) {
            maxSum = Math.max(maxSum, max_sum_increasing_subseq(a, n, i, k) + a[i]);
        }
    }
    return Math.max(maxSum, max_sum_increasing_subseq(a, n, index + 1, k));
}

