function min_Swaps(str1, str2){
    let count = 0;
    let i = 0;
    let j = 0;

    // Find the first mismatch
    while (i < str1.length && j < str2.length && str1[i] === str2[j]) {
        i++;
        j++;
    }

    // If all characters match, no swaps are needed
    if (i === str1.length) {
        return count;
    }

    // Find the next mismatch
    while (j < str2.length && str2[j] === str1[i]) {
        j++;
    }

    // If all characters match, no swaps are needed
    if (j === str2.length) {
        return count;
    }

    // Find the next mismatch
    while (i < str1.length && j < str2.length && str1[i] !== str2[j]) {
        i++;
        j++;
    }

    // Calculate the number of swaps needed
    count += i - j;

    // Find the next mismatch
    while (i < str1.length && j < str2.length && str1[i] !== str2[j]) {
        i++;
        j++;
    }

    // Calculate the number of swaps needed
    count += j - i;

    return count;
}

