function max_sum_increasing_subseq(a, n, index, k) {
    // Initialize a 2D array to store the maximum sum of increasing subsequence up to each index including the kth element
    const dp = Array.from({ length: n }, () => Array.from({ length: k + 1 }, () => 0));

    // Iterate through the array to fill the dp table
    for (let i = 0; i < n; i++) {
        for (let j = 1; j <= k; j++) {
            if (i === 0 || a[i] > a[i - 1]) {
                // If the current element is greater than the previous element or it's the first element, add the current element to the dp table
                dp[i][j] = Math.max(dp[i - 1][j], a[i]);
            } else {
                // If the current element is not greater than the previous element, skip it
                dp[i][j] = dp[i - 1][j];
            }
        }
    }

    // Find the maximum sum of increasing subsequence up to the last index including the kth element
    let maxSum = 0;
    for (let j = 1; j <= k; j++) {
        maxSum = Math.max(maxSum, dp[n - 1][j]);
    }

    return maxSum;
}

