    let dp = Array.from({ length: n }, () => 0);
    let max_sum = 0;

    for (let i = 0; i < n; i++) {
        dp[i] = a[i];
        for (let j = 0; j < i; j++) {
            if (a[j] < a[i] && dp[i] < dp[j] + a[i]) {
                dp[i] = dp[j] + a[i];
            }
        }
        if (index < i && k > i) {
            dp[i] += a[k];
        }
        max_sum = Math.max(max_sum, dp[i]);
    }

    return max_sum;
}

