function minPath(grid, k) {
  const n = grid.length;
  const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
  let visited = new Array(n).fill(0).map(() => new Array(n).fill(false));
  let minPathLength = Infinity;
  let minPathValues = [];

  const dfs = (x, y, path, pathLength) => {
    if (pathLength === k) {
      if (path.length < minPathLength || path.length === minPathLength && path.join('') < minPathValues.join('')) {
        minPathLength = path.length;
        minPathValues = path;
      }
      return;
    }

    for (const [dx, dy] of directions) {
      const nx = x + dx;
      const ny = y + dy;
      if (nx >= 0 && nx < n && ny >= 0 && ny < n && !visited[nx][ny]) {
        visited[nx][ny] = true;
        dfs(nx, ny, [...path, grid[nx][ny]], pathLength + 1);
        visited[nx][ny] = false;
      }
    }
  };

  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      dfs(i, j, [grid[i][j]], 1);
    }
  }

  return minPathValues;
}

function minPath(grid, k) {
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];

  function getNeighbors(x, y) {
    return directions.filter(([dx, dy]) => x + dx >= 0 && x + dx < N && y + dy >= 0 && y + dy < N);
  }

  const dp = Array.from({ length: N }, () => Array(N).fill(null));
  const visited = Array.from({ length: N }, () => Array(N).fill(false));

  function dfs(x, y, path) {
    if (path.length === k) {
      return [path.slice()];
    }

    if (dp[x][y] !== null) {
      return dp[x][y];
    }

    dp[x][y] = [];

    for (const [dx, dy] of getNeighbors(x, y)) {
      if (!visited[x + dx][y + dy]) {
        visited[x + dx][y + dy] = true;
        dp[x][y].push(...dfs(x + dx, y + dy, [...path, grid[x + dx][y + dy]]));
        visited[x + dx][y + dy] = false;
      }
    }

    return dp[x][y];
  }

  const minPathValues = [];
  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      minPathValues.push(...dfs(i, j, [grid[i][j]]));
    }
  }

  minPathValues.sort((a, b) => a.toString() < b.toString() ? -1 : 1);

  return minPathValues[0];
}

