function min_Jumps(steps, d) {
    // Calculate the number of jumps required
    let jumps = 0;
    let remainingDistance = d;

    while (remainingDistance > 0) {
        // If steps are greater than remainingDistance, take all steps
        if (steps >= remainingDistance) {
            jumps++;
            remainingDistance = 0;
        } else {
            // Otherwise, take one step and reduce remainingDistance by one
            jumps++;
            remainingDistance--;
        }
    }

    return jumps;
}

