function eulerian_num(n, m) {
  if (n < m) return 0; // Eulerian numbers are non-negative
  if (n === m) return 1; // Base case: A permutation of n elements is a permutation of n elements

  // Initialize the result
  let result = 0;

  // Calculate the Eulerian number using the recurrence relation
  for (let i = 0; i <= n; i++) {
    result += (-1) ** i * Math.pow(m, n - i) * Math.pow(n - i, m);
  }

  return result;
}

