function get_total_number_of_sequences(m, n) {
  if (n === 1) {
    return m;
  }

  let total = 0;
  for (let i = 2; i <= m; i++) {
    total += get_total_number_of_sequences(m, n - 1);
  }

  return total;
}

function get_total_number_of_sequences(m, n) {
  // Base case: If n is 0, there's only one sequence (the empty sequence).
  if (n === 0) return 1;

  // Initialize a DP array to store the number of sequences for each length up to n.
  const dp = new Array(n + 1).fill(0);
  dp[0] = 1; // Base case: There's one way to have a sequence of length 0 (the empty sequence).

  // Fill the DP array.
  for (let i = 1; i <= n; i++) {
    for (let j = 2; j <= m; j++) {
      if (j >= i * 2) {
        dp[i] = (dp[i] + dp[i - 1]) % 1000000007; // Add the number of valid sequences ending with j to the total.
      }
    }
  }

  return dp[n]; // Return the total number of sequences for length n.
}

function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
    let minPathLength = Infinity;
    let minPath = [];

    function dfs(row, col, path, length) {
        if (length === k) {
            if (length < minPathLength || (length === minPathLength && path < minPath)) {
                minPathLength = length;
                minPath = path.slice();
            }
            return;
        }

        for (const [dr, dc] of directions) {
            const newRow = row + dr;
            const newCol = col + dc;
            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited[newRow][newCol]) {
                visited[newRow][newCol] = true;
                dfs(newRow, newCol, path.concat([grid[newRow][newCol]]), length + 1);
                visited[newRow][newCol] = false;
            }
        }
    }

    const visited = Array.from({ length: N }, () => Array(N).fill(false));
    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, [grid[i][j]], 1);
        }
    }

    return minPath;
}

function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];

    const visited = new Array(N).fill().map(() => new Array(N).fill(false));
    const distance = new Array(N).fill().map(() => new Array(N).fill(Infinity));
    const path = new Array(k).fill(0);

    const dfs = (x, y, steps) => {
        if (steps === k) {
            path[steps - 1] = grid[x][y];
            return;
        }

        visited[x][y] = true;
        distance[x][y] = steps;

        for (const [dx, dy] of directions) {
            const nx = x + dx;
            const ny = y + dy;

            if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny]) {
                dfs(nx, ny, steps + 1);
            }
        }

        visited[x][y] = false;
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, 0);
        }
    }

    let minDistance = Infinity;
    let minPathIndex = -1;

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            if (distance[i][j] === k && distance[i][j] < minDistance) {
                minDistance = distance[i][j];
                minPathIndex = [i, j];
            }
        }
    }

    return path.slice(0, minDistance + 1);
}

