function bell_Number(n) {
  // Initialize an array to store bell numbers
  const bell = new Array(n + 1).fill(0);

  // Base case: Bell number for n=0 is 1
  bell[0] = 1;

  // Calculate the Bell numbers using the recursive formula
  for (let i = 1; i <= n; i++) {
    for (let j = 0; j < i; j++) {
      bell[i] += bell[j] * bell[i - j - 1];
    }
  }

  return bell[n];
}

function bell_Number(n){
  if (n <= 0) return 0;
  if (n === 1) return 1;
  let bell = [0, 1];
  for (let i = 2; i <= n; i++) {
    let bell_i = 0;
    for (let j = 0; j < i; j++) {
      bell_i += bell[j] * bell[i - j - 1];
    }
    bell.push(bell_i);
  }
  return bell[n];
}

