function generate_integers(a, b) {
  // Ensure a is less than or equal to b
  if (a > b) {
    [a, b] = [b, a];
  }

  // Initialize an empty array to store even digits
  let evenDigits = [];

  // Loop through each digit from a to b
  for (let i = a; i <= b; i++) {
    // Convert the current digit to a string to check each digit
    const digitStr = i.toString();
    // Check if the digit is even
    if (digitStr.includes('0') || digitStr.includes('2') || digitStr.includes('4') || digitStr.includes('6') || digitStr.includes('8')) {
