function max_sum_increasing_subseq(a, n, index, k) {
    let dp = new Array(n).fill(0);
    let max_sum = 0;

    for (let i = index; i < n; i++) {
        dp[i] = a[i];
        for (let j = 0; j < i; j++) {
            if (a[j] < a[i] && dp[j] + a[i] > dp[i]) {
                dp[i] = dp[j] + a[i];
            }
        }
        max_sum = Math.max(max_sum, dp[i]);
    }

    for (let i = index + 1; i < n; i++) {
        if (a[k] > a[i] && dp[i] + a[k] > dp[k]) {
            dp[k] = dp[i] + a[k];
        }
        max_sum = Math.max(max_sum, dp[k]);
    }

    return max_sum;
}

function max_sum_increasing_subseq(a, n, index, k) {
    if (index === n) {
        return 0;
    }

    let sum = 0;
    for (let i = index + 1; i < n; i++) {
        if (a[i] > a[index] && i > k) {
            sum = Math.max(sum, a[index] + max_sum_increasing_subseq(a, n, i, k));
        }
    }

    return Math.max(sum, max_sum_increasing_subseq(a, n, index + 1, k));
}

