function group_tuples(Input) {
  // Convert the array of arrays into a single array of tuples
  const flattenedArray = Input.flat();

  // Find the first element that appears in all tuples
  const firstElement = flattenedArray.reduce((acc, val) => {
    if (acc.includes(val)) {
      return acc;
    }
    return [...acc, val];
  }, []);

  // Remove duplicates by converting the array back to a set
  const uniqueFirstElement = [...new Set(firstElement)];

  // Return the first element
  return uniqueFirstElement[0];
}

