        path = [...visited[x][y].slice(1)];
      }
      return;
    }

    for (const [dx, dy] of directions) {
      const nx = x + dx;
      const ny = y + dy;
      if (nx >= 0 && nx < n && ny >= 0 && ny < n && !visited[nx][ny][length]) {
        visited[nx][ny][length] = true;
        dfs(nx, ny, length + 1);
        visited[nx][ny][length] = false;
      }
    }
  }

  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      visited[i][j][0] = true;
      dfs(i, j, 1);
      visited[i][j][0] = false;
    }
  }

  return path;
}

function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const visited = new Set();
    const queue = new Queue();
    const path = new Array(k + 1).fill(0);

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            queue.enqueue({ row: i, col: j, path: [grid[i][j]] });
            visited.add(`${i},${j}`);
        }
    }

    while (!queue.isEmpty()) {
        const { row, col, path } = queue.dequeue();

        if (path.length === k + 1) {
            return path;
        }

        for (const [dr, dc] of directions) {
            const newRow = row + dr;
            const newCol = col + dc;

            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited.has(`${newRow},${newCol}`)) {
                visited.add(`${newRow},${newCol}`);
                queue.enqueue({ row: newRow, col: newCol, path: [...path, grid[newRow][newCol]] });
            }
        }
    }

    return []; // In case no path is found
}

