    const digits = n.toString().split('');
    let found = false;

    // Iterate through the digits in reverse order
    for (let i = digits.length - 2; i >= 0; i--) {
        // If the current digit is less than the next digit
        if (digits[i] < digits[i + 1]) {
            // Find the smallest digit to the right of the current digit that is greater than it
            let j = i + 1;
            while (j < digits.length && digits[j] <= digits[i]) {
                j++;
            }

            // Swap the digits
            [digits[i], digits[j - 1]] = [digits[j - 1], digits[i]];

            // Sort the digits to the right of the current digit in ascending order
            digits.splice(i + 1, digits.length - i - 1).sort((a, b) => a - b);

            // Convert the array of digits back to a number
            const result = parseInt(digits.join(''));

            // Return the result if it is greater than the original number
            if (result > n) {
                found = true;
                return result;
            }
        }
    }

    // Return -1 if no bigger number can be formed
    return -1;
}

