function minPath(grid, k) {
    const rows = grid.length;
    const cols = grid[0].length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];

    const visited = new Array(rows).fill().map(() => new Array(cols).fill(false));
    const distances = new Array(rows).fill().map(() => new Array(cols).fill(Infinity));
    const paths = new Array(rows).fill().map(() => new Array(cols).fill(null));

    const start = [0, 0];
    distances[start[0]][start[1]] = 0;
    paths[start[0]][start[1]] = [grid[start[0]][start[1]]];

    const minDistance = Infinity;
    let minPathCells = [];

    const dfs = (i, j, distance) => {
        if (distance === k) {
            if (distance < minDistance) {
                minDistance = distance;
                minPathCells = [...paths[i][j]];
            } else if (distance === minDistance) {
                minPathCells = minPathCells.concat(paths[i][j]);
            }
            return;
        }

        for (const [dx, dy] of directions) {
            const x = i + dx;
            const y = j + dy;

            if (x >= 0 && x < rows && y >= 0 && y < cols && !visited[x][y] && distances[x][y] + 1 <= distance) {
                visited[x][y] = true;
                distances[x][y] = distance + 1;
                paths[x][y] = [...paths[i][j], grid[x][y]];
                dfs(x, y, distance + 1);
                visited[x][y] = false;
                paths[x][y] = paths[i][j];
            }
        }
    };

    dfs(start[0], start[1], 0);

    return minPathCells;
}

function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]]; // Right, Down, Left, Up
    const visited = new Set();
    const path = new Array(k).fill(0);
    const minPathLength = Infinity;
    const minPath = [];

    const dfs = (i, j, pathLength, path) => {
        if (pathLength === k) {
            if (path.join(',') < minPath.join(',')) {
                minPath = [...path];
                minPathLength = pathLength;
            }
            return;
        }

        if (i < 0 || i >= N || j < 0 || j >= N || visited.has(`${i},${j}`)) {
            return;
        }

        visited.add(`${i},${j}`);
        path[pathLength] = grid[i][j];
        dfs(i + directions[0][0], j + directions[0][1], pathLength + 1, path);
        dfs(i + directions[1][0], j + directions[1][1], pathLength + 1, path);
        dfs(i + directions[2][0], j + directions[2][1], pathLength + 1, path);
        dfs(i + directions[3][0], j + directions[3][1], pathLength + 1, path);
        visited.delete(`${i},${j}`);
        path.pop();
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, 0, []);
        }
    }

    return minPath;
}

