  let digits = n.toString().split('').map(Number);

  // Find the first digit that is smaller than the digit immediately after it
  let i = digits.length - 2;
  while (i >= 0 && digits[i] >= digits[i + 1]) {
    i--;
  }

  // If no such digit is found, the number is already the largest permutation
  if (i === -1) {
    return -1;
  }

  // Find the smallest digit to the right of i that is greater than digits[i]
  let j = digits.length - 1;
  while (j > i && digits[j] <= digits[i]) {
    j--;
  }

  // Swap digits[i] and digits[j]
  [digits[i], digits[j]] = [digits[j], digits[i]];

  // Reverse the digits to the right of i
  let left = i + 1;
  let right = digits.length - 1;
  while (left < right) {
    [digits[left], digits[right]] = [digits[right], digits[left]];
    left++;
    right--;
  }

  // Convert the array of digits back to a number
  return parseInt(digits.join(''), 10);
}

