function find_combinations(test_list){
  const result = [];
  const length = test_list.length;

  function backtrack(start, currentSum, path) {
    if (currentSum === 0) {
      result.push([...path]);
      return;
    }

    for (let i = start; i < length; i++) {
      if (currentSum - test_list[i] >= 0) {
        backtrack(i + 1, currentSum - test_list[i], [...path, test_list[i]]);
      }
    }
  }

  backtrack(0, 0, []);

  return result;
}

function find_combinations(test_list) {
