    if (steps === k) {
      minPath.push([...path]);
      return;
    }

    for (const [dx, dy] of directions) {
      const x = i + dx;
      const y = j + dy;

      if (x >= 0 && x < N && y >= 0 && y < N && !visited[x][y]) {
        visited[x][y] = true;
        path.push(grid[x][y]);
        dfs(x, y, steps + 1);
        path.pop();
        visited[x][y] = false;
      }
    }
  };

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
