function rearrange_bigger(n) {
    let digits = Array.from(String(n), Number);
    let len = digits.length;

    // Find the first digit that is smaller than the digit immediately after it
    let i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    if (i === -1) {
        // If no such digit is found, the number is the largest permutation
        return -1;
    }

    // Find the smallest digit on the right side of i that is greater than digits[i]
    let j = len - 1;
    while (j >= i && digits[j] <= digits[i]) {
        j--;
    }

    // Swap digits[i] and digits[j]
    [digits[i], digits[j]] = [digits[j], digits[i]];

    // Reverse the digits to the right of i
    let left = i + 1, right = len - 1;
    while (left < right) {
        [digits[left], digits[right]] = [digits[right], digits[left]];
        left++;
        right--;
    }

    // Convert the array of digits back to a number
    return parseInt(digits.join(''), 10);
}

function rearrange_bigger(n) {
  // Convert the number to an array of digits
  const digits = n.toString().split('');

  // Find the first digit from the right that is smaller than the digit immediately to its right
  let i = digits.length - 2;
  while (i >= 0 && digits[i] >= digits[i + 1]) {
    i--;
  }

  // If no such digit is found, the number is already the largest possible
  if (i === -1) {
    return -1; // No bigger number can be formed
  }

  // Find the smallest digit to the right of 'i' that is greater than digits[i]
  let j = digits.length - 1;
  while (digits[j] <= digits[i]) {
    j--;
  }

  // Swap 'i' and 'j'
  [digits[i], digits[j]] = [digits[j], digits[i]];

  // Sort the digits to the right of 'i' in ascending order
  const rightPart = digits.slice(i + 1).sort((a, b) => a - b);

  // Combine the digits to form the new number
  const rearrangedNumber = parseInt(digits.slice(0, i + 1).join('') + rightPart.join(''));

  return rearrangedNumber;
}

