function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const visited = new Array(N).fill().map(() => new Array(N).fill(false));
    const path = [];
    const minPath = [];

    const dfs = (row, col, steps) => {
        if (steps === k) {
            minPath.push([...path]);
            return;
        }

        for (const [dr, dc] of directions) {
            const newRow = row + dr;
            const newCol = col + dc;
            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited[newRow][newCol]) {
                visited[newRow][newCol] = true;
                path.push(grid[newRow][newCol]);
                dfs(newRow, newCol, steps + 1);
                path.pop();
                visited[newRow][newCol] = false;
            }
        }
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            visited[i][j] = true;
            path.push(grid[i][j]);
            dfs(i, j, 1);
            path.pop();
            visited[i][j] = false;
        }
    }

    minPath.sort((a, b) => {
        for (let i = 0; i < a.length; i++) {
            if (a[i] !== b[i]) {
                return a[i] - b[i];
            }
        }
        return 0;
    });

    return minPath[0];
}

function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const visited = new Array(N).fill().map(() => new Array(N).fill(false));
    const pq = new PriorityQueue((a, b) => a[0] < b[0]);
    const visitedNodes = new Set();

    const getNeighbors = (i, j) => {
        const neighbors = [];
        for (const [dx, dy] of directions) {
            const x = i + dx;
            const y = j + dy;
            if (x >= 0 && x < N && y >= 0 && y < N && !visited[x][y]) {
                neighbors.push([x, y]);
            }
        }
        return neighbors;
    };

    const dfs = (i, j, path, steps) => {
        if (steps === k) {
            pq.push([path.join(' '), 0]);
            return;
        }

        visited[i][j] = true;
        visitedNodes.add(`${i},${j}`);

        for (const [x, y] of getNeighbors(i, j)) {
            dfs(x, y, path + grid[x][y], steps + 1);
        }

        visited[i][j] = false;
        visitedNodes.delete(`${i},${j}`);
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, grid[i][j], 1);
        }
    }

    pq.sort((a, b) => a[1] - b[1]);
    return pq.peek()[0].split(' ').map(Number);
}

