function minPath(grid, k) {
    const rows = grid.length;
    const cols = grid[0].length;
    const visited = new Array(rows).fill().map(() => new Array(cols).fill(false));

    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];

    function dfs(row, col, path) {
        if (path.length === k) {
            return path;
        }

        visited[row][col] = true;

        for (const [dx, dy] of directions) {
            const newRow = row + dx;
            const newCol = col + dy;

            if (newRow >= 0 && newRow < rows && newCol >= 0 && newCol < cols && !visited[newRow][newCol]) {
                const newPath = [...path, grid[newRow][newCol]];
                const result = dfs(newRow, newCol, newPath);
                if (result) {
                    return result;
                }
            }
        }

        visited[row][col] = false;
        return null;
    }

    let minPathValue = Infinity;
    let minPath = [];

    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            const path = dfs(i, j, [grid[i][j]]);
            if (path && path.length === k && path.join(',') < minPathValue.toString()) {
                minPathValue = path.join(',');
                minPath = path;
            }
        }
    }

    return minPath;
}

