        minPath = [...path];
        minSteps = path.length;
      }
      return;
    }

    const directions = [
      { row: 1, col: 0 },
      { row: -1, col: 0 },
      { row: 0, col: 1 },
      { row: 0, col: -1 }
    ];

    for (const dir of directions) {
      const newRow = i + dir.row;
      const newCol = j + dir.col;

