function minPath(grid, k){
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
  const visited = new Array(N).fill().map(() => new Array(N).fill(false));
  const path = [];
  const minPathValues = [];

  const dfs = (x, y, steps) => {
    if (steps === k) {
      minPathValues.push([...path]);
      return;
    }

    for (const [dx, dy] of directions) {
      const nx = x + dx;
      const ny = y + dy;

      if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny]) {
        visited[nx][ny] = true;
        path.push(grid[nx][ny]);
        dfs(nx, ny, steps + 1);
        path.pop();
        visited[nx][ny] = false;
      }
    }
  };

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      if (!visited[i][j]) {
        visited[i][j] = true;
        path.push(grid[i][j]);
        dfs(i, j, 1);
        path.pop();
        visited[i][j] = false;
      }
    }
  }

  minPathValues.sort((a, b) => {
    for (let i = 0; i < a.length && i < b.length; i++) {
      if (a[i] !== b[i]) {
        return a[i] - b[i];
      }
    }
    return a.length - b.length;
  });

  return minPathValues[0];
}

function minPath(grid, k){
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]]; // Right, Down, Left, Up
    let minPath = [];

    function backtrack(x, y, path, steps) {
        if (steps === k) {
            minPath = path.slice();
            return;
        }

        for (let i = 0; i < 4; i++) {
            const newX = x + directions[i][0];
            const newY = y + directions[i][1];

            if (newX >= 0 && newX < N && newY >= 0 && newY < N && !path.includes(grid[newX][newY])) {
                path.push(grid[newX][newY]);
                backtrack(newX, newY, path, steps + 1);
                path.pop();
            }
        }
    }

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            backtrack(i, j, [grid[i][j]], 1);
        }
    }

    return minPath;
}

