function rearrange_bigger(n) {
    let digits = n.toString().split('');
    let maxIndex = digits.length - 1;

    // Find the first digit that is smaller than the digit immediately after it.
    while (maxIndex > 0 && digits[maxIndex - 1] >= digits[maxIndex]) {
        maxIndex--;
    }

    if (maxIndex === 0) {
        return -1; // The number is the largest possible permutation.
    }

    // Find the largest digit to the right of maxIndex that is greater than digits[maxIndex - 1].
    let swapIndex = maxIndex + 1;
    for (let i = maxIndex + 1; i < digits.length; i++) {
        if (digits[i] > digits[maxIndex - 1] && digits[i] <= digits[swapIndex]) {
            swapIndex = i;
        }
    }

    // Swap digits[maxIndex - 1] and digits[swapIndex].
    [digits[maxIndex - 1], digits[swapIndex]] = [digits[swapIndex], digits[maxIndex - 1]];

    // Sort the digits to the right of maxIndex.
    digits.splice(maxIndex, digits.length - maxIndex).sort();

    // Combine the digits to form the next bigger number.
    return parseInt(digits.join(''));
}

function rearrange_bigger(n) {
    let digits = n.toString().split('');
    let sortedDigits = digits.slice().sort((a, b) => b - a);
    let i = digits.length - 1;

    while (i >= 0 && digits[i] >= sortedDigits[i]) {
        i--;
    }

    if (i === -1) {
        return -1; // No bigger number can be formed
    }

    let j = i + 1;
    while (j < digits.length && digits[j] <= sortedDigits[i]) {
        j++;
    }

    [digits[i], digits[j]] = [digits[j], digits[i]];

    digits.splice(i + 1);

    sortedDigits.splice(i, 1);

    return parseInt(digits.join('')) + parseInt(sortedDigits.join(''));
}

