function find_combinations(test_list) {
  const result = [];

  // Helper function to generate combinations recursively
  function generate_combinations(index, current_sum, current_combination) {
    if (current_combination.length > 0) {
      result.push(current_combination.slice()); // Add a copy of the current combination to the result
    }

    for (let i = index; i < test_list.length; i++) {
      generate_combinations(i + 1, current_sum + test_list[i], current_combination.concat([test_list[i]]));
    }
  }

  generate_combinations(0, 0, []); // Start the recursion with the first index and sum 0

  return result;
}

function find_combinations(test_list){
    let combinations = [];
    function backtrack(start, currentSum, currentCombination) {
        if (currentSum === 0) {
            combinations.push(currentCombination.slice());
            return;
        }
        for (let i = start; i < test_list.length; i++) {
            currentCombination.push(test_list[i]);
            backtrack(i + 1, currentSum - test_list[i], currentCombination);
            currentCombination.pop();
        }
    }
    backtrack(0, 0, []);
    return combinations;
}

