function bell_Number(n) {
  // Initialize the first few Bell numbers
  const bell = [1, 1, 2, 5, 15, 52, 156, 421, 1323, 4210];

  // If n is less than or equal to the length of the bell array, return the corresponding Bell number
  if (n <= bell.length) {
    return bell[n - 1];
  }

  // Calculate the nth Bell number using the recursive formula
  let result = 0;
  for (let i = 0; i <= n; i++) {
    result += bell[i] * bell[n - i - 1];
  }

  // Return the calculated Bell number
  return result;
}

function bell_Number(n) {
  if (n === 0) return 1;
  let bell = [1];
  for (let i = 1; i <= n; i++) {
    let nextBell = 0;
    for (let j = 0; j < i; j++) {
      nextBell += bell[j] * bell[i - j - 1];
    }
    bell.push(nextBell);
  }
  return bell[n];
}

