    const visited = new Array(N).fill().map(() => new Array(N).fill(false));
    const path = [];
    const minPathValue = Infinity;
    const minPathIndex = 0;

    const dfs = (row, col, steps) => {
        if (steps === k) {
            if (path.length < minPathValue || (path.length === minPathValue && path.join(',') < minPathValue.join(','))) {
                minPathValue = path.join(',');
                minPathIndex = path.length;
            }
            return;
        }

        if (row < 0 || row >= N || col < 0 || col >= N || visited[row][col]) {
            return;
        }

        visited[row][col] = true;
        path.push(grid[row][col]);

        for (const [dx, dy] of directions) {
            dfs(row + dx, col + dy, steps + 1);
        }

        path.pop();
        visited[row][col] = false;
    };

    for (let i = 0; i < N; i++) {
