function max_sum_increasing_subseq(a, n, index, k) {
  // Initialize a 2D array to store the maximum sum of increasing subsequence
  const dp = new Array(n).fill(0).map(() => new Array(k + 1).fill(0));

  // Base case: The sum of an empty subsequence is 0
  for (let i = 0; i < n; i++) {
    dp[i][0] = 0;
  }

  // Fill the dp array
  for (let i = 1; i < n; i++) {
    for (let j = 1; j <= k; j++) {
      // If the current element is greater than the previous element and the sum of the increasing subsequence up to the previous element plus the current element is greater than the sum of the increasing subsequence up to the current element and the previous element plus the given kth element, update the dp array
      if (a[i] > a[i - 1] && dp[i - 1][j] + a[i] > dp[i - 1][j - 1] + a[i]) {
        dp[i][j] = dp[i - 1][j] + a[i];
      } else {
        dp[i][j] = dp[i - 1][j - 1] + a[i];
      }
    }
  }

  // The maximum sum of increasing subsequence up to the last element and including the given kth element is the maximum value in the dp array
  return Math.max(...dp[n - 1]);
}

function max_sum_increasing_subseq(a, n, index, k) {
  if (index === n - 1) {
    return a[index];
  }

  let maxSum = a[index];
  for (let i = index + 1; i < n; i++) {
    if (a[i] > a[index] && i > k) {
      maxSum = Math.max(maxSum, max_sum_increasing_subseq(a, n, i, k) + a[i]);
    }
  }

  return maxSum;
}

