    // Iterate through the array to find the maximum sum of increasing subsequence
    for (let i = index + 1; i < n; i++) {
        if (a[i] > a[index]) {
            dp[i] = Math.max(dp[i], dp[index] + a[i]);
        }
    }

    // Initialize the result for the kth element
    let result = 0;

    // Iterate through the array to find the maximum sum of increasing subsequence including the kth element
    for (let i = 0; i < index; i++) {
        if (a[i] < a[k] && dp[i] > 0) {
