function rearrange_bigger(n) {
    let digits = n.toString().split('');
    let len = digits.length;
    let found = false;

    for (let i = len - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            let j = len - 1;
            while (digits[j] <= digits[i]) {
                j--;
            }
            [digits[i], digits[j]] = [digits[j], digits[i]];
            digits.splice(i + 1, len - i - 1, ...digits.splice(i + 1, 0, ...digits.splice(i, 1)));
            found = true;
            break;
        }
    }

    if (!found) {
        return -1;
    }

    return parseInt(digits.join(''));
}

function rearrange_bigger(n){
    // Convert number to string to manipulate digits
    let str = n.toString();
    let len = str.length;

    // Find the first digit from the right that is smaller than the digit immediately to its right
    for (let i = len - 2; i >= 0; i--) {
        if (str[i] < str[i + 1]) {
            // Find the smallest digit to the right of the found digit that is greater than it
            let j = len - 1;
            while (str[j] <= str[i]) {
                j--;
            }

            // Swap the found digits
            let temp = str[i];
            str[i] = str[j];
            str[j] = temp;

            // Sort the digits to the right of the swapped digit
            str = str.slice(0, i + 1) + str.slice(i + 1).split('').sort().join('');

            // Convert the string back to number and return
            return parseInt(str, 10);
        }
    }

    // If no bigger number can be formed, return -1
    return -1;
}

