function minPath(grid, k) {
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
  const visited = new Array(N).fill().map(() => new Array(N).fill(false));
  const path = new Array(k).fill(0);
  const minPath = [];

  const dfs = (x, y, steps) => {
    if (steps === k) {
      minPath.push([...path]);
      return;
    }
    for (let i = 0; i < 4; i++) {
      const nx = x + directions[i][0];
      const ny = y + directions[i][1];
      if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny]) {
        visited[nx][ny] = true;
        path[steps] = grid[nx][ny];
        dfs(nx, ny, steps + 1);
        visited[nx][ny] = false;
        path[steps] = 0;
      }
    }
  };

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      visited[i][j] = true;
      path[0] = grid[i][j];
      dfs(i, j, 1);
      visited[i][j] = false;
    }
  }

  minPath.sort((a, b) => a.join('') < b.join('') ? -1 : 1);

  return minPath[0];
}

function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    let minPath = [];

    function dfs(row, col, path, steps) {
        if (steps === k) {
            minPath = path.slice();
            return;
        }

        for (const [dr, dc] of directions) {
            const newRow = row + dr;
            const newCol = col + dc;

            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !path.includes(grid[newRow][newCol])) {
                dfs(newRow, newCol, path.concat(grid[newRow][newCol]), steps + 1);
            }
        }
    }

    for (let row = 0; row < N; row++) {
        for (let col = 0; col < N; col++) {
            dfs(row, col, [grid[row][col]], 1);
        }
    }

    return minPath;
}

