    let maxIndex = -1;

    for (let i = n - 1; i >= 0; i--) {
        if (prev[i] !== -1) {
            let sum = dp[i];
            let j = i;
            while (prev[j] !== -1) {
                sum += a[j];
                j = prev[j];
            }
            if (sum > maxSum) {
                maxSum = sum;
                maxIndex = i;
            }
        }
    }

    if (maxIndex === -1) {
        return 0;
    }

    let result = 0;
    let j = maxIndex;
    while (prev[j] !== -1) {
        result += a[j];
        j = prev[j];
    }

    return result;
}

function max_sum_increasing_subseq(a, n, index, k) {
    if (index === n) return 0;
    if (index === n - 1) return a[index];

    let maxSum = a[index];
    for (let i = index + 1; i < n; i++) {
        if (a[i] > a[index]) {
            maxSum = Math.max(maxSum, max_sum_increasing_subseq(a, n, i, k) + a[i]);
        }
    }

    let maxSumWithK = 0;
    if (k < n && a[k] > a[index]) {
        maxSumWithK = max_sum_increasing_subseq(a, n, k, k) + a[k];
    }

    return Math.max(maxSum, maxSumWithK);
}

