function find_combinations(test_list) {
    const results = [];
    const backtrack = (index, currentSum, currentCombination) => {
        if (currentSum === test_list.length) {
            results.push([...currentCombination]);
            return;
        }
        for (let i = index; i < test_list.length; i++) {
            currentCombination.push(test_list[i]);
            backtrack(i + 1, currentSum + test_list[i], currentCombination);
            currentCombination.pop();
        }
    };
    backtrack(0, 0, []);
    return results;
}

function find_combinations(test_list) {
  const result = [];

  // Helper function to generate combinations
  function generate_combinations(arr, start, target, current) {
    if (target === 0) {
      result.push([...current]);
      return;
    }
    if (target < 0 || start >= arr.length) {
      return;
    }

    // Include the current element
    current.push(arr[start]);
    generate_combinations(arr, start + 1, target - arr[start], current);

    // Exclude the current element
    current.pop();
    generate_combinations(arr, start + 1, target, current);
  }

  // Start the recursion with the first element
  generate_combinations(test_list, 0, test_list[0], []);

  return result;
}

