function get_total_number_of_sequences(m, n) {
    if (n === 1) return 1; // Only one sequence of length 1 is possible
    if (n > m) return 0; // No sequences of length n can be formed with m or more elements

    let count = 0;
    for (let i = 2; i <= m; i++) {
        count += get_total_number_of_sequences(m - i, n - 1);
    }
    return count;
}

function get_total_number_of_sequences(m, n) {
  // Initialize a 2D array to store the number of sequences for each length and value
  const dp = Array.from({ length: n + 1 }, () => Array.from({ length: m + 1 }, () => 0));

  // Base case: There is one way to have a sequence of length 1 with any value
  for (let i = 1; i <= m; i++) {
    dp[1][i] = 1;
  }

  // Fill the dp array
  for (let i = 2; i <= n; i++) {
    for (let j = 2; j <= m; j++) {
      dp[i][j] = dp[i - 1][j]; // No change in the previous element
      if (j >= 2 * (i - 1)) {
        dp[i][j] += dp[i - 1][j - 2 * (i - 1)]; // Include the previous element
      }
    }
  }

  // The total number of sequences of length n with values from 1 to m
  return dp[n][m];
}

