  // Initialize the sum variable
  let sum = 0;

  // Iterate from 1 to n
  for (let i = 1; i <= n; i++) {
    // Calculate the binomial coefficient C(n, i)
    const binomialCoefficient = Math.comb(n, i);

    // Multiply the binomial coefficient by the product of consecutive integers from i to n
    const product = Array.from({ length: n - i + 1 }, (_, j) => j + 1).reduce((acc, val) => acc * val, 1);

    // Add the product to the sum
