    if (steps === k) {
      path.push(grid[x][y]);
      return;
    }
    for (const [dx, dy] of directions) {
      const nx = x + dx;
      const ny = y + dy;
      if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny]) {
        visited[nx][ny] = true;
        dfs(nx, ny, steps + 1);
        visited[nx][ny] = false;
      }
    }
  }

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      visited[i][j] = true;
      dfs(i, j, 1);
      visited[i][j] = false;
    }
  }

  path.sort((a, b) => a - b);
  return path;
}

