    function backtrack(start, currentSum, path) {
        if (currentSum === 0) {
            result.push(path.slice());
            return;
        }
        for (let i = start; i < test_list.length; i++) {
            if (test_list[i] > currentSum) continue;
            path.push(test_list[i]);
            backtrack(i + 1, currentSum - test_list[i], path);
