function rearrange_bigger(n){
    // Convert number to string to easily manipulate digits
    const digits = n.toString().split('');
    const length = digits.length;

    // Start from the second last digit and move towards the first
    for (let i = length - 2; i >= 0; i--) {
        // Find the first digit that is smaller than the digit immediately after it
        for (let j = i + 1; j < length; j++) {
            if (digits[i] < digits[j]) {
                // Swap these two digits
                [digits[i], digits[j]] = [digits[j], digits[i]];
                // Sort the remaining digits in descending order
                digits.splice(i + 1).sort((a, b) => b - a);
                // Combine the sorted digits back into a number
                return parseInt(digits.join(''));
            }
        }
    }
    // If no larger number can be formed, return -1
    return -1;
}

function rearrange_bigger(n) {
  // Convert the number to an array of its digits
  const digits = n.toString().split('');

  // Find the first digit that is smaller than the digit immediately after it
  let i = digits.length - 2;
  while (i >= 0 && digits[i] >= digits[i + 1]) {
    i--;
  }

  // If no such digit is found, the number is the largest possible permutation
  if (i === -1) {
    return -1;
  }

  // Find the smallest digit to the right of the found digit that is larger than it
  let j = digits.length - 1;
  while (j >= 0 && digits[j] <= digits[i]) {
    j--;
  }

  // Swap the found digits
  [digits[i], digits[j]] = [digits[j], digits[i]];

  // Sort the digits to the right of the swapped digit in ascending order
  digits.splice(i + 1).sort((a, b) => a - b);

  // Convert the array of digits back to a number
  return parseInt(digits.join(''), 10);
}

function max_sum_increasing_subseq(a, n, index, k) {
    if (index === n - 1 && k === n) {
        return a[index];
    }
    if (index >= n) {
        return 0;
    }
    if (k >= n) {
        return max_sum_increasing_subseq(a, n, index + 1, k);
    }
    const include = a[index] + max_sum_increasing_subseq(a, n, index + 1, k);
    const exclude = max_sum_increasing_subseq(a, n, index + 1, k);
    return Math.max(include, exclude);
}

function max_sum_increasing_subseq(a, n, index, k) {
    if (index === n) {
        return 0;
    }

    let maxSum = 0;
    for (let i = index + 1; i < n; i++) {
        if (a[index] < a[i] && i > k) {
            maxSum = Math.max(maxSum, a[index] + max_sum_increasing_subseq(a, n, i, k));
        }
    }

    return Math.max(maxSum, max_sum_increasing_subseq(a, n, index + 1, k));
}

