function minPath(grid, k) {
  const N = grid.length;
  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const visited = new Array(N).fill().map(() => new Array(N).fill(false));
  const path = [];
  const minPathLength = Infinity;
  const minPath = [];

  const dfs = (x, y, steps) => {
    if (steps === k) {
      if (path.length < minPathLength || (path.length === minPathLength && path.join(',') < minPath.join(','))) {
        minPathLength = path.length;
        minPath = [...path];
      }
      return;
    }

    for (const [dx, dy] of directions) {
      const nx = x + dx;
      const ny = y + dy;
      if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny]) {
        visited[nx][ny] = true;
        path.push(grid[nx][ny]);
        dfs(nx, ny, steps + 1);
        path.pop();
        visited[nx][ny] = false;
      }
    }
  };

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      visited[i][j] = true;
      path.push(grid[i][j]);
      dfs(i, j, 1);
      path.pop();
      visited[i][j] = false;
    }
  }

  return minPath;
}

