function get_total_number_of_sequences(m, n){
    if (n === 1) return 1; // Base case: only one sequence of length 1
    let total = 0;
    for (let i = 2; i <= m; i++) {
        total += get_total_number_of_sequences(m, n - 1);
    }
    return total;
}

function get_total_number_of_sequences(m, n) {
    // Base case: If n is 1, there's only one sequence: the number itself
    if (n === 1) {
        return 1;
    }

    // Initialize a 2D array to store the number of sequences for each length
    let dp = Array.from({ length: n + 1 }, () => Array.from({ length: m + 1 }, () => 0));

    // Fill the dp array
    for (let i = 1; i <= n; i++) {
        for (let j = 1; j <= m; j++) {
            // If i is 1, there's only one way to choose the number (it's itself)
            if (i === 1) {
                dp[i][j] = 1;
            } else {
                // For each number j, the previous number can be any number from 1 to j/2
                for (let k = 1; k <= Math.min(j, m / 2); k++) {
                    dp[i][j] += dp[i - 1][k];
                }
            }
        }
    }

    // The total number of sequences is the number of sequences of length n with the last number less than or equal to m
    return dp[n][m];
}

