function minPath(grid, k) {
    const n = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const visited = new Array(n).fill().map(() => new Array(n).fill(false));
    const minPathLength = Infinity;
    let minPath = [];

    const dfs = (i, j, path, pathLength) => {
        if (pathLength === k) {
            if (path.length < minPathLength) {
                minPath = [...path];
                minPathLength = path.length;
            }
            return;
        }

        for (const [dx, dy] of directions) {
            const x = i + dx;
            const y = j + dy;
            if (x >= 0 && x < n && y >= 0 && y < n && !visited[x][y]) {
                visited[x][y] = true;
                dfs(x, y, [...path, grid[x][y]], pathLength + 1);
                visited[x][y] = false;
            }
        }
    };

    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            visited[i][j] = true;
            dfs(i, j, [grid[i][j]], 1);
            visited[i][j] = false;
        }
    }

    return minPath;
}

function minPath(grid, k) {
    const rows = grid.length;
    const cols = grid[0].length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const visited = new Array(rows).fill(null).map(() => new Array(cols).fill(false));
    const path = [];
    let minPathValue = Infinity;

    function dfs(x, y, steps) {
        if (steps === k) {
            if (path.length < minPathValue || (path.length === minPathValue && path.join(',') < minPathValue.join(','))) {
                minPathValue = path.join(',');
                minPath = [...path];
            }
            return;
        }

        for (const [dx, dy] of directions) {
            const nx = x + dx;
            const ny = y + dy;
            if (nx >= 0 && nx < rows && ny >= 0 && ny < cols && !visited[nx][ny]) {
                visited[nx][ny] = true;
                path.push(grid[nx][ny]);
                dfs(nx, ny, steps + 1);
                path.pop();
                visited[nx][ny] = false;
            }
        }
    }

    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            visited[i][j] = true;
            path.push(grid[i][j]);
            dfs(i, j, 1);
            path.pop();
            visited[i][j] = false;
        }
    }

    return minPath;
}

