  let bell = [1];
  for (let i = 1; i <= n; i++) {
    let prev = bell[i - 1];
    for (let j = 0; j < i; j++) {
      bell[i] += prev * bell[j];
    }
  }
  return bell[n];
}

function bell_Number(n) {
