function rearrange_bigger(n) {
    const digits = n.toString().split('');
    let i = digits.length - 2;

    // Find the first digit from the right that is smaller than the digit immediately to its right.
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    if (i === -1) {
        // If no such digit is found, return -1.
        return -1;
    }

    // Find the smallest digit to the right of the found digit that is greater than the digit.
    let j = digits.length - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap the found digits.
    [digits[i], digits[j]] = [digits[j], digits[i]];

    // Sort the digits to the right of the swapped digit.
    const rightPart = digits.slice(i + 1).sort((a, b) => a - b);

    // Combine the digits.
    return parseInt(digits.slice(0, i + 1).join('') + rightPart.join(''));
}

function rearrange_bigger(n) {
  let digits = n.toString().split('');
  let len = digits.length;

  for (let i = len - 2; i >= 0; i--) {
    if (digits[i] < digits[i + 1]) {
      for (let j = len - 1; j > i; j--) {
        if (digits[j] > digits[i]) {
          [digits[i], digits[j]] = [digits[j], digits[i]];
          break;
        }
      }
      digits.splice(i + 1);
      digits.sort((a, b) => a - b);
      return parseInt(digits.join(''));
    }
  }

  return -1;
}

