function sequence(n) {
  if (n === 0) return 0;
  if (n === 1) return 1;

  const memo = new Map();
  memo.set(0, 0);
  memo.set(1, 1);

  function findNewman(n) {
    if (memo.has(n)) return memo.get(n);

    const a = findNewman(n - 1);
