function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
    const visited = new Array(N).fill().map(() => new Array(N).fill(false));
    const path = [];
    const minPath = [];

    function dfs(row, col, steps) {
        if (steps === k) {
            minPath.push(...path);
            return;
        }

        if (row < 0 || row >= N || col < 0 || col >= N || visited[row][col]) {
            return;
        }

        visited[row][col] = true;
        path.push(grid[row][col]);

        for (const [dr, dc] of directions) {
            dfs(row + dr, col + dc, steps + 1);
        }

        path.pop();
        visited[row][col] = false;
    }

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, 0);
        }
    }

    minPath.sort((a, b) => a - b);
    return minPath;
}

function minPath(grid, k) {
    let n = grid.length;
    let directions = [[0, 1], [1, 0], [-1, 0], [0, -1]]; // Right, Down, Up, Left
    let visited = new Array(n).fill().map(() => new Array(n).fill(false));
    let minPath = [];

    function dfs(row, col, steps, path) {
        if (steps === k) {
            minPath.push(path.slice());
            return;
        }

        for (let i = 0; i < 4; i++) {
            let newRow = row + directions[i][0];
            let newCol = col + directions[i][1];

            if (newRow >= 0 && newRow < n && newCol >= 0 && newCol < n && !visited[newRow][newCol]) {
                visited[newRow][newCol] = true;
                dfs(newRow, newCol, steps + 1, path.concat(grid[newRow][newCol]));
                visited[newRow][newCol] = false;
            }
        }
    }

    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            visited = new Array(n).fill().map(() => new Array(n).fill(false));
            dfs(i, j, 1, [grid[i][j]]);
        }
    }

    minPath.sort((a, b) => a.join('') < b.join('') ? -1 : 1);
    return minPath[0];
}

