function max_sum_increasing_subseq(a, n, index, k) {
    // Initialize a 2D array to store the maximum sum of increasing subsequence
    const dp = Array.from({ length: n }, () => Array(k + 1).fill(0));

    // Base case: If the index is 0, the maximum sum is 0
    dp[0][1] = a[0];

    // Fill the dp array
    for (let i = 1; i < n; i++) {
        for (let j = 1; j <= k; j++) {
            dp[i][j] = Math.max(dp[i - 1][j], dp[i - 1][j - 1] + a[i]);
            dp[i][j] = Math.max(dp[i][j], dp[i][j] + a[i]);
        }
    }

    // The maximum sum of increasing subsequence from prefix until ith index and also including a given kth element which is after i
    return dp[n - 1][k];
}

function max_sum_increasing_subseq(a, n, index, k) {
    if (index >= n) {
        return 0;
    }

    let maxSum = a[index];
    for (let i = index + 1; i < n; i++) {
        if (a[i] > a[index] && i > k) {
            maxSum = Math.max(maxSum, a[i] + max_sum_increasing_subseq(a, n, i, k));
        }
    }

    return maxSum;
}

