function find_combinations(test_list){
    const results = [];

    function backtrack(start, currentSum, currentCombination) {
        if (currentCombination.length === test_list.length) {
            results.push(currentCombination.slice());
            return;
        }

        for (let i = start; i < test_list.length; i++) {
            currentCombination.push(test_list[i]);
            backtrack(i + 1, currentSum + test_list[i], currentCombination);
            currentCombination.pop();
        }
    }

    backtrack(0, 0, []);
    return results;
}

function find_combinations(test_list) {
    const result = [];
    const length = test_list.length;
    const sum = test_list.reduce((acc, val) => acc + val, 0);

    const backtrack = (currentSum, index) => {
        if (currentSum === sum) {
            result.push(currentSum);
            return;
        }

        if (currentSum > sum || index >= length) {
            return;
        }

        backtrack(currentSum + test_list[index], index + 1);
        backtrack(currentSum, index + 1);
    };

    backtrack(0, 0);
    return result;
}

