function max_product(arr) {
  // Initialize the maximum product to the smallest possible number
  let max_product = Number.NEGATIVE_INFINITY;
  // Initialize the current product to 1
  let current_product = 1;

  // Iterate through the array to find the maximum product
  for (let i = 0; i < arr.length; i++) {
    // Update the current product by multiplying it with the current number
    current_product *= arr[i];
    // Update the maximum product if the current product is greater
    max_product = Math.max(max_product, current_product);
