function newman_shanks_williams(num) {
    let a = 2, b = 1, d = 2, t = 0, s = 0;

    while (true) {
        let x = (a * a - b * b) % num;
        let y = 2 * a * b % num;

        if (x === 0) {
            return true; // Found a prime number
        }

        if (x === 1) {
            return false; // No prime number found
        }

        if (y === 1) {
            return false; // No prime number found
        }

        if (x === y) {
            return false; // No prime number found
        }

        if (x > y) {
            t = x - y;
            s = s + 1;
        } else {
            t = y - x;
            s = s - 1;
        }

        if (s === 0) {
            s = num - 1;
        }

        if (s === 1) {
            return false; // No prime number found
        }

        if (s === num - 1) {
            return true; // Found a prime number
        }

        a = t;
        b = y;
        d = 2 * d;
    }
}

