  for (let i = 1; i < arr.length; i++) {
    // Initialize the current product with the current element
    let currentProduct = arr[i];

    // Iterate through the subsequence starting from the current element
    for (let j = i - 1; j >= 0; j--) {
      // Update the current product by multiplying with the current element
      currentProduct *= arr[j];

      // Update the maximum product if the current product is greater
      if (currentProduct > maxProduct) {
