function minPath(grid, k) {
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
  const visited = new Set();
  const queue = [{ row: 0, col: 0, steps: 0 }];
  const minPath = [];

  while (queue.length && minPath.length < k) {
    const { row, col, steps } = queue.shift();

    if (steps === k) {
      minPath.push(grid[row][col]);
      continue;
    }

    for (const [dx, dy] of directions) {
      const newRow = row + dx;
      const newCol = col + dy;

      if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited.has(`${newRow},${newCol}`)) {
        visited.add(`${newRow},${newCol}`);
        queue.push({ row: newRow, col: newCol, steps: steps + 1 });
      }
    }
  }

  return minPath;
}

function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]]; // Right, Down, Up, Left
    let minPath = [];
    let visited = new Set();

    function dfs(i, j, path, steps) {
        if (steps === k) {
            minPath = [...path];
            return;
        }

        if (i < 0 || i >= N || j < 0 || j >= N || visited.has(`${i},${j}`)) {
            return;
        }

        visited.add(`${i},${j}`);
        path.push(grid[i][j]);

        for (const [dx, dy] of directions) {
            dfs(i + dx, j + dy, path, steps + 1);
        }

        path.pop();
        visited.delete(`${i},${j}`);
    }

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, [], 0);
        }
    }

    return minPath;
}

