function find_combinations(test_list) {
  const result = [];

  function backtrack(start, currentSum, currentCombination) {
    if (currentSum === 0) {
      result.push(currentCombination.slice());
      return;
    }

    for (let i = start; i < test_list.length; i++) {
      currentCombination.push(test_list[i]);
      backtrack(i + 1, currentSum - test_list[i], currentCombination);
      currentCombination.pop();
    }
  }

  backtrack(0, 0, []);
  return result;
}

function find_combinations(test_list){
    let combinations = [];
    function backtrack(index, currentSum, currentCombination) {
        if (currentSum === 0) {
            combinations.push([...currentCombination]);
            return;
        }
        if (index >= test_list.length || currentSum < 0) {
            return;
        }
        currentCombination.push(test_list[index]);
        backtrack(index + 1, currentSum - test_list[index], currentCombination);
        currentCombination.pop();
        backtrack(index + 1, currentSum, currentCombination);
    }
    backtrack(0, 0, []);
    return combinations;
}

