function rearrange_bigger(n){
    // Convert the number to an array of digits
    let digits = Array.from(String(n), Number);

    // Find the first digit from the right that is smaller than the digit immediately to its right
    let i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such digit is found, the number is the largest possible permutation
    if (i < 0) {
        return -1;
    }

    // Find the smallest digit to the right of i that is greater than digits[i]
    let j = digits.length - 1;
    while (j > i && digits[j] <= digits[i]) {
        j--;
    }

    // Swap digits[i] and digits[j]
    [digits[i], digits[j]] = [digits[j], digits[i]];

    // Reverse the digits to the right of i
    digits.splice(i + 1);
    digits.reverse();

    // Convert the array of digits back to a number
    return parseInt(digits.join(''), 10);
}

function max_sum_increasing_subseq(a, n, index, k) {
    if (index === n - 1) {
        return a[index];
    }

    let maxSum = a[index];
    for (let i = index + 1; i < n && i <= k; i++) {
        maxSum = Math.max(maxSum, a[index] + max_sum_increasing_subseq(a, n, i, k));
    }

    return maxSum;
}

function max_sum_increasing_subseq(a, n, index, k) {
    // Initialize a 2D array to store the maximum sum for each subsequence ending at index i
    const dp = Array.from({ length: n }, () => Array(k + 1).fill(0));

    // Base case: If index is 0, the maximum sum is the value of the first element
    if (index === 0) {
        dp[index][0] = a[index];
        return dp[index][0];
    }

    // Iterate through the array to fill the dp table
    for (let i = 1; i < n; i++) {
        for (let j = 1; j <= k; j++) {
            // If the current element is greater than the previous element, update the dp table
            if (a[i] > a[index - 1]) {
                dp[i][j] = Math.max(dp[i][j], dp[index - 1][j] + a[i]);
            }
            // If the current element is equal to the previous element, update the dp table
            if (a[i] === a[index - 1]) {
                dp[i][j] = Math.max(dp[i][j], dp[index - 1][j]);
            }
        }
    }

    // Find the maximum sum of the increasing subsequence ending at index n-1 and including a given kth element
    let max_sum = 0;
    for (let j = 1; j <= k; j++) {
        max_sum = Math.max(max_sum, dp[n - 1][j]);
    }

    return max_sum;
}

