function max_sum_increasing_subseq(a, n, index, k) {
    // Initialize a 2D array to store the maximum sum of increasing subsequence up to each index
    const dp = Array.from({ length: n }, () => Array.from({ length: k + 1 }, () => 0));

    // Base case: The maximum sum of increasing subsequence up to the first index is the value itself
    dp[0][0] = a[0];

    // Fill the dp array
    for (let i = 1; i < n; i++) {
        for (let j = 0; j <= k; j++) {
            // If the current element is greater than the element at index j in the previous subsequence
            if (j === 0 || a[i] > a[j - 1]) {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i - 1][j - 1] + a[i]);
            } else {
                dp[i][j] = dp[i - 1][j];
            }
        }
    }

    // The maximum sum of increasing subsequence up to the last index including the kth element
    return dp[n - 1][k];
}

function max_sum_increasing_subseq(a, n, index, k) {
  let dp = new Array(n + 1).fill(0);
  let prev = new Array(n + 1).fill(-1);

  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j <= n; j++) {
      if (a[i] < a[j] && dp[i] + a[j] > dp[j]) {
        dp[j] = dp[i] + a[j];
        prev[j] = i;
      }
    }
  }

  let maxSum = 0;
  let maxIndex = -1;
  for (let i = n - 1; i >= index + 1; i--) {
    if (prev[i] !== -1 && prev[i] > index) {
      maxSum = dp[i];
      maxIndex = i;
      break;
    }
  }

  if (maxIndex === -1) {
    return 0;
  }

  let sum = a[maxIndex];
  for (let i = maxIndex - 1; i >= index + 1; i--) {
    if (prev[i] === maxIndex) {
      sum += a[i];
    }
  }

  return sum;
}

