    if (n === 0) {
        return 1;
    }
    if (m === 0) {
        return 1;
    }
    if (m > n) {
        return 0;
    }

    // Recursive case
    return (n - m) * eulerian_num(n - 1, m - 1) + (m + 1) * eulerian_num(n - 1, m);
}

