function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const visited = new Array(N).fill().map(() => new Array(N).fill(false));
    const path = [];
    const minPathLength = Infinity;
    const minPathValues = [];

    const dfs = (x, y, steps, path) => {
        if (steps === k) {
            if (path.length < minPathLength || (path.length === minPathLength && path.join(',') < minPathValues.join(','))) {
                minPathLength = path.length;
                minPathValues = path.slice();
            }
            return;
        }

        for (const [dx, dy] of directions) {
            const newX = x + dx;
            const newY = y + dy;
            if (newX >= 0 && newX < N && newY >= 0 && newY < N && !visited[newX][newY]) {
                visited[newX][newY] = true;
                path.push(grid[newX][newY]);
                dfs(newX, newY, steps + 1, path);
                path.pop();
                visited[newX][newY] = false;
            }
        }
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            visited[i][j] = true;
            dfs(i, j, 1, [grid[i][j]]);
            visited[i][j] = false;
        }
    }

    return minPathValues;
}

function minPath(grid, k) {
