function minPath(grid, k) {
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
  const visited = new Set();
  const minPath = [];

  const dfs = (x, y, path) => {
    if (path.length === k) {
      minPath.push(path);
      return;
    }
    for (const [dx, dy] of directions) {
      const nx = x + dx;
      const ny = y + dy;
      if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited.has(`${nx},${ny}`)) {
        visited.add(`${nx},${ny}`);
        dfs(nx, ny, [...path, grid[nx][ny]]);
        visited.delete(`${nx},${ny}`);
      }
    }
  };

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      visited.add(`${i},${j}`);
      dfs(i, j, [grid[i][j]]);
      visited.delete(`${i},${j}`);
    }
  }

  minPath.sort((a, b) => a.join(',') < b.join(',') ? -1 : 1);

  return minPath[0];
}

function minPath(grid, k) {
    const N = grid.length;
    const visited = new Array(N).fill(0).map(() => new Array(N).fill(false));
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const minPathLength = Infinity;
    let minPath = [];

    const dfs = (row, col, path, steps) => {
        if (steps === k) {
            if (path.length < minPathLength) {
                minPath = path.slice();
                minPathLength = path.length;
            }
            return;
        }

        if (row < 0 || row >= N || col < 0 || col >= N || visited[row][col]) {
            return;
        }

        visited[row][col] = true;
        path.push(grid[row][col]);

        for (const [dr, dc] of directions) {
            dfs(row + dr, col + dc, path, steps + 1);
        }

        path.pop();
        visited[row][col] = false;
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, [], 0);
        }
    }

    return minPath;
}

